/**
 * ContactLookupAction
 *
 * Flow action (label: "Find Contact by Email") that resolves Contacts by email
 * address for a whole batch of requests using a single SOQL query.
 *
 * Behaviour
 * - Returns exactly one Result per Request, in the same order as the incoming list.
 * - Email matching is case-insensitive and ignores leading/trailing whitespace.
 * - A blank / null email, or an email that no Contact has, yields
 *   found = false and contactId = null.
 * - When several Contacts share the same email, the one with the earliest
 *   CreatedDate is returned (ties are broken deterministically by Id).
 * - At most one SOQL query is executed per invocation, regardless of batch size.
 * - The running user's record sharing is enforced (see "with sharing" below).
 */
public with sharing class ContactLookupAction {

    /**
     * Invocable method used by Flow.
     *
     * @param requests Batch of email lookups (Flow may pass up to 200).
     * @return         One Result per Request, in the same order as `requests`.
     */
    @InvocableMethod(
        label = 'Find Contact by Email'
        description = 'Finds an existing Contact by email address. Matching is case-insensitive and ignores leading/trailing spaces. If multiple Contacts share the email, the one created earliest is returned. Returns found = false when no Contact matches.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // ------------------------------------------------------------------
        // 1. Normalize the requested emails and collect the distinct set of
        //    keys we need to query for.
        // ------------------------------------------------------------------
        Set<String> emailKeys = new Set<String>();
        for (Request request : requests) {
            if (request == null) {
                continue;
            }
            String key = normalize(request.email);
            if (key != null) {
                emailKeys.add(key);
            }
        }

        // ------------------------------------------------------------------
        // 2. Single SOQL query. LOWER(TRIM(Email)) makes the match
        //    case-insensitive and tolerant of whitespace stored on the record.
        //    Ordering by CreatedDate (then Id) means the FIRST row we see for
        //    any given email is the oldest Contact holding that email.
        // ------------------------------------------------------------------
        Map<String, Contact> oldestContactByEmail = new Map<String, Contact>();

        if (!emailKeys.isEmpty()) {
            List<Contact> matches = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE LOWER(TRIM(Email)) IN :emailKeys
                ORDER BY CreatedDate ASC, Id ASC
                LIMIT 20000
            ];

            for (Contact contact : matches) {
                String key = normalize(contact.Email);
                if (key == null || !emailKeys.contains(key)) {
                    continue;
                }
                if (!oldestContactByEmail.containsKey(key)) {
                    oldestContactByEmail.put(key, contact);
                }
            }
        }

        // ------------------------------------------------------------------
        // 3. Project the map back onto the original request order so the
        //    caller always receives one Result per Request, in the same order.
        // ------------------------------------------------------------------
        for (Request request : requests) {
            Result result = new Result();
            result.contactId = null;
            result.found = false;

            if (request != null) {
                String key = normalize(request.email);
                if (key != null && oldestContactByEmail.containsKey(key)) {
                    result.contactId = oldestContactByEmail.get(key).Id;
                    result.found = true;
                }
            }

            results.add(result);
        }

        return results;
    }

    /**
     * Normalizes an email address for comparison: trims leading/trailing
     * whitespace and lower-cases the value.
     *
     * @param value Raw email value (may be null).
     * @return      Normalized key, or null when the value is null/blank.
     */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        if (String.isBlank(trimmed)) {
            return null;
        }
        return trimmed.toLowerCase();
    }

    /**
     * Input model for the "Find Contact by Email" action.
     */
    public class Request {
        @InvocableVariable(
            label = 'Email'
            description = 'Email address of the Contact to look up. Matching is case-insensitive and ignores leading/trailing spaces.'
            required = true
        )
        public String email;
    }

    /**
     * Output model for the "Find Contact by Email" action.
     */
    public class Result {
        @InvocableVariable(
            label = 'Contact Id'
            description = 'Id of the matching Contact, or null when no Contact was found.'
        )
        public Id contactId;

        @InvocableVariable(
            label = 'Found'
            description = 'True when a Contact with the supplied email address exists.'
        )
        public Boolean found;
    }
}
