/**
 * PicklistService
 *
 * Runtime utility that returns the active values of any picklist (or multi-select
 * picklist) field, standard or custom, in the order the values are defined on the field.
 *
 * Design notes
 *  - Metadata is read through the Schema describe API only: no SOQL is issued, so the
 *    utility is cheap, bulk safe and works for every object/field combination without
 *    needing per-object query code.
 *  - All failures are surfaced as PicklistService.PicklistServiceException so callers
 *    never have to deal with NullPointerException, DescribeException or SObjectException.
 *  - Object and field API names are matched case-insensitively ('account' / 'INDUSTRY').
 *
 * Example
 *   for (PicklistService.Option opt : PicklistService.activeOptions('FB_Asset_Check__c', 'Status__c')) {
 *       System.debug(opt.value + ' | ' + opt.label + ' | default=' + opt.isDefault);
 *   }
 */
public with sharing class PicklistService {
    /**
     * A single picklist entry.
     *
     * @value      the API value of the picklist entry (what is stored on the record)
     * @label      the display label of the picklist entry
     * @isDefault  true only for the entry that is the default value of the field
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }

        public override String toString() {
            return 'Option{value=\'' + value + '\', label=\'' + label + '\', isDefault=' + isDefault + '}';
        }
    }

    /** Custom exception raised for every error condition of this service. */
    public class PicklistServiceException extends Exception {
    }

    /**
     * Returns the active options of a picklist / multi-select picklist field,
     * in the order they are defined on the field. Inactive values are omitted.
     *
     * @param objectApiName API name of the object (case-insensitive, standard or custom)
     * @param fieldApiName  API name of the picklist field (case-insensitive)
     * @return list of Option (never null)
     * @throws PicklistServiceException when a name is null/blank, the object or the field
     *         does not exist, or the field is not a picklist / multi-select picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // ---------- input validation -------------------------------------------------
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('objectApiName is required and cannot be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('fieldApiName is required and cannot be null or blank.');
        }

        String requestedObject = objectApiName.trim();
        String requestedField = fieldApiName.trim();

        try {
            // ---------- resolve the object --------------------------------------------
            Schema.SObjectType soType = findSObjectType(requestedObject);
            if (soType == null) {
                throw new PicklistServiceException(
                    'Object "' + requestedObject + '" does not exist in this organization.'
                );
            }

            Schema.DescribeSObjectResult objectDescribe = soType.getDescribe();

            // ---------- resolve the field ---------------------------------------------
            Schema.SObjectField field = findField(objectDescribe, requestedField);
            if (field == null) {
                throw new PicklistServiceException(
                    'Field "' + requestedField + '" does not exist on object "' + objectDescribe.getName() + '".'
                );
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();

            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field "' + objectDescribe.getName() + '.' + fieldDescribe.getName() + '" is of type '
                    + String.valueOf(fieldType) + ' and is not a picklist or multi-select picklist field.'
                );
            }

            // ---------- read the picklist entries --------------------------------------
            List<Schema.PicklistValue> picklistValues = fieldDescribe.getPicklistValues();

            List<Option> options = new List<Option>();
            if (picklistValues == null) {
                return options;
            }

            for (Schema.PicklistValue picklistValue : picklistValues) {
                if (picklistValue == null) {
                    continue;
                }
                // Inactive values are left out.
                if (!picklistValue.isActive()) {
                    continue;
                }
                options.add(new Option(
                    picklistValue.getValue(),
                    picklistValue.getLabel(),
                    picklistValue.isDefaultValue()
                ));
            }
            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            // Never leak another exception type to the caller.
            throw new PicklistServiceException(
                'Unable to read picklist options for "' + requestedObject + '.' + requestedField
                + '": ' + e.getMessage()
            );
        }
    }

    /**
     * Case-insensitive lookup of an SObject type by API name.
     * @return the SObjectType or null when the object does not exist
     */
    private static Schema.SObjectType findSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        if (globalDescribe == null) {
            return null;
        }
        if (globalDescribe.containsKey(objectApiName)) {
            return globalDescribe.get(objectApiName);
        }
        for (String key : globalDescribe.keySet()) {
            if (key != null && key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    /**
     * Case-insensitive lookup of a field on the described object.
     * @return the SObjectField or null when the field does not exist / is not visible
     */
    private static Schema.SObjectField findField(Schema.DescribeSObjectResult objectDescribe, String fieldApiName) {
        Map<String, Schema.SObjectField> fields = objectDescribe.fields;
        if (fields == null) {
            return null;
        }
        if (fields.containsKey(fieldApiName)) {
            return fields.get(fieldApiName);
        }
        for (String key : fields.keySet()) {
            if (key != null && key.equalsIgnoreCase(fieldApiName)) {
                return fields.get(key);
            }
        }
        return null;
    }
}
