/**
 * Publishes warehouse shipment notifications as platform events.
 *
 * The platform event FB_Shipment_Event__e is configured as "publish after commit",
 * so events are delivered only once the current transaction commits successfully.
 */
public with sharing class ShipmentEventPublisher {

    /** Value object describing a single parcel leaving the warehouse. */
    public class Shipment {
        public String orderNumber;
        public String trackingNumber;
        public String carrier;

        public Shipment(String orderNumber, String trackingNumber, String carrier) {
            this.orderNumber = orderNumber;
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }

    /**
     * Publishes one FB_Shipment_Event__e per shipment, in a single publish call.
     *
     * Shipments with a blank order number are skipped.
     *
     * @param shipments shipments to publish (may be null or empty)
     * @return the number of events published successfully
     */
    public static Integer publishShipments(List<ShipmentEventPublisher.Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> events = new List<FB_Shipment_Event__e>();
        for (ShipmentEventPublisher.Shipment shipment : shipments) {
            if (shipment == null) {
                continue;
            }
            if (String.isBlank(shipment.orderNumber)) {
                // Without an order number the event cannot be matched to an order.
                continue;
            }

            FB_Shipment_Event__e event = new FB_Shipment_Event__e();
            event.Order_Number__c = shipment.orderNumber.trim().toUpperCase();
            event.Tracking_Number__c = shipment.trackingNumber;
            event.Carrier__c = shipment.carrier;
            events.add(event);
        }

        if (events.isEmpty()) {
            return 0;
        }

        // Single publish call for the whole batch.
        List<Database.SaveResult> results = EventBus.publish(events);

        Integer published = 0;
        for (Database.SaveResult result : results) {
            if (result.isSuccess()) {
                published++;
            } else {
                for (Database.Error error : result.getErrors()) {
                    System.debug(
                        'Shipment event publish failed [' + error.getStatusCode() + ']: ' + error.getMessage()
                    );
                }
            }
        }
        return published;
    }
}
