 * Consumes FB_Shipment_Event__e platform events and marks the matching sales orders as shipped.
 *
 * Guaranteed behaviour per call:
 *  - exactly one SOQL query
 *  - at most one DML statement (bulk safe, no per-event DML)
 */
public with sharing class ShipmentEventHandler {

    private static final String STATUS_SHIPPED = 'Shipped';
    private static final String STATUS_CANCELLED = 'Cancelled';

    /**
     * @param events platform events received (may be null or empty)
     */
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // --- Collect the distinct order numbers referenced by the events -------------
        Set<String> orderNumbers = new Set<String>();
        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }
            orderNumbers.add(event.Order_Number__c.trim().toUpperCase());
        }
        if (orderNumbers.isEmpty()) {
            return;
        }

        // --- Single SOQL query -------------------------------------------------------
        Map<String, FB_Sales_Order__c> ordersByNumber = new Map<String, FB_Sales_Order__c>();
        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderNumbers
        ];
        for (FB_Sales_Order__c order : orders) {
            if (order.Order_Number__c == null) {
                continue;
            }
            ordersByNumber.put(order.Order_Number__c.trim().toUpperCase(), order);
        }

        // --- Build the records to update ---------------------------------------------
        // Keyed by order number so that, when several events refer to the same order,
        // the last event in the list wins.
        Map<String, FB_Sales_Order__c> updatesByNumber = new Map<String, FB_Sales_Order__c>();
        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }
            String orderNumber = event.Order_Number__c.trim().toUpperCase();

            FB_Sales_Order__c order = ordersByNumber.get(orderNumber);
            if (order == null) {
                // Event for an unknown order number: ignore it.
                continue;
            }
            if (STATUS_CANCELLED.equals(order.Status__c)) {
                // Cancelled orders are never changed.
                continue;
            }

            FB_Sales_Order__c updatedOrder = new FB_Sales_Order__c(Id = order.Id);
            updatedOrder.Status__c = STATUS_SHIPPED;
            updatedOrder.Tracking_Number__c = event.Tracking_Number__c;
            updatedOrder.Carrier__c = event.Carrier__c;
            updatedOrder.Shipped_Date__c = Date.today();

            updatesByNumber.put(orderNumber, updatedOrder);
        }

        // --- Single DML statement ----------------------------------------------------
        if (!updatesByNumber.isEmpty()) {
            update new List<FB_Sales_Order__c>(updatesByNumber.values());
        }
    }
}
