```apex
/**
 * Queueable job that flags Accounts as synchronized with the ERP.
 *
 * Every execution registers an ErpSyncFinalizer *before* doing any work, so that a
 * FB_Job_Log__c row is written whether the transaction succeeds or fails. If the DML
 * fails the exception is deliberately NOT caught: the transaction is rolled back
 * (all-or-nothing) and the finalizer records the failure and schedules a retry.
 */
public with sharing class ErpAccountSyncJob implements Queueable {

    /** Attempt used for the very first run. */
    private static final Integer DEFAULT_ATTEMPT = 1;

    /** Value written to Account.Description for a synchronized account. */
    private static final String SYNCED_DESCRIPTION = 'Synced to ERP';

    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds Ids of the Accounts to flag as synced.
     * @param attempt    1 for the first run, incremented by the finalizer on every retry.
     */
    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = filterAccountIds(accountIds);
        this.attempt = (attempt == null) ? DEFAULT_ATTEMPT : attempt;
    }

    public void execute(QueueableContext context) {
        // 1. Attach the finalizer first: it must run for this transaction whatever the outcome.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        if (accountIds.isEmpty()) {
            return;
        }

        // 2. Load the accounts to update.
        List<Account> accounts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
        ];

        if (accounts.isEmpty()) {
            // Nothing left to sync (accounts were deleted in the meantime).
            return;
        }

        // 3. Flag every account as synced.
        for (Account account : accounts) {
            account.Description = SYNCED_DESCRIPTION;
        }

        // 4. Single, all-or-nothing DML statement. If any record cannot be saved an
        //    uncaught DmlException is raised: the transaction is rolled back so that
        //    none of the changes are kept, and the finalizer logs the failure.
        update accounts;
    }

    /**
     * Keeps only valid Account Ids so that a malformed id can never break the query.
     */
    private static Set<Id> filterAccountIds(Set<Id> ids) {
        Set<Id> filtered = new Set<Id>();
        if (ids == null) {
            return filtered;
        }
        for (Id id : ids) {
            if (id == null) {
                continue;
            }
            try {
                if (Id.getSObjectType() == Account.SObjectType) {
                    filtered.add(id);
                }
            } catch (Exception e) {
                // Not a valid id - ignore it.
            }
        }
        return filtered;
    }
}
