/**
 * OpportunityTrigger
 *
 * Thin, logic-free trigger: it only collects the affected Opportunities and
 * delegates every decision to OpportunityPipelineHandler.
 *
 * Events covered:
 *   - insert    : new opportunity (account pipeline/count grows)
 *   - update    : Amount change, StageName/IsClosed change (open <-> closed),
 *                 or AccountId change (both the old and the new account change)
 *   - delete    : opportunity disappears (pipeline/count shrink, 0/0 when the
 *                 last open opportunity is removed)
 *   - undelete  : opportunity comes back (pipeline/count grow again)
 */
trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {
    // Trigger.new is empty for deletes, Trigger.old is empty for inserts/undeletes.
    // The handler unions the AccountIds of both lists, so a moved opportunity
    // updates the old account as well as the new one.
    OpportunityPipelineHandler.handle(Trigger.new, Trigger.old);
}
