/**
 * OpportunityPipelineHandler
 *
 * Maintains, purely in Apex (the Account object has no free roll-up summary
 * fields left):
 *
 *   Account.FB_Open_Pipeline__c      Currency - SUM of Amount of the account's
 *                                              open opportunities (IsClosed = false).
 *                                              Blank Amount counts as 0.
 *   Account.FB_Open_Opportunities__c  Number  - COUNT of the account's open
 *                                              opportunities.
 *
 * Design notes:
 *   - The totals are always re-derived from the database with one aggregate
 *     query, so they are correct after every DML statement (insert, update,
 *     delete, undelete, account move) and for bulk loads (200+ opportunities
 *     are handled with a single query, never with per-record SOQL).
 *   - Only Accounts whose values actually change are written. This is what
 *     keeps the handler safe in the presence of the existing AccountTrigger,
 *     which updates Opportunities on every Account update and therefore
 *     re-fires this trigger: the second pass detects "no change" and performs
 *     no DML, so the chain converges instead of looping.
 *   - An account whose last open opportunity goes away is set to 0 and 0
 *     (never null/blank).
 */
public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point called by OpportunityTrigger.
     *
     * @param newOpps Opportunities in the new state (empty for deletes).
     * @param oldOpps Opportunities in the previous state (empty for inserts/undeletes).
     */
    public static void handle(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        Set<Id> accountIds = new Set<Id>();
        collectAccountIds(newOpps, accountIds);
        collectAccountIds(oldOpps, accountIds);

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    /**
     * Adds the AccountId of every opportunity to the set of accounts to refresh.
     */
    private static void collectAccountIds(List<Opportunity> opps, Set<Id> accountIds) {
        if (opps == null) {
            return;
        }
        for (Opportunity opp : opps) {
            if (opp != null && opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    /**
     * Recomputes and stores both roll-up fields for the given accounts.
     * Runs a fixed number of queries (2 SOQL + at most 1 DML) no matter how
     * many opportunities or accounts are involved.
     */
    private static void recalculate(Set<Id> accountIds) {
        // ---- 1. Aggregate the open opportunities of the affected accounts ----
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();

        List<Opportunity> openOpps = [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
        ];

        for (Opportunity opp : openOpps) {
            Decimal amount = (opp.Amount == null) ? Decimal.valueOf(0) : opp.Amount;

            Decimal currentPipeline = pipelineByAccount.containsKey(opp.AccountId)
                ? pipelineByAccount.get(opp.AccountId)
                : Decimal.valueOf(0);
            pipelineByAccount.put(opp.AccountId, currentPipeline + amount);

            Integer currentCount = openCountByAccount.containsKey(opp.AccountId)
                ? openCountByAccount.get(opp.AccountId)
                : 0;
            openCountByAccount.put(opp.AccountId, currentCount + 1);
        }

        // ---- 2. Read the current stored values -------------------------------
        Map<Id, Account> currentAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        // ---- 3. Write only the accounts that really change -------------------
        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            Account current = currentAccounts.get(accountId);
            if (current == null) {
                // Account no longer exists (or is not visible) - nothing to update.
                continue;
            }

            // Accounts with no open opportunity left must show 0 and 0, not blank.
            Decimal pipeline = pipelineByAccount.containsKey(accountId)
                ? pipelineByAccount.get(accountId)
                : Decimal.valueOf(0);
            Integer openCount = openCountByAccount.containsKey(accountId)
                ? openCountByAccount.get(accountId)
                : 0;

            // Guard against pointless DML: this also stops the AccountTrigger
            // (which updates Opportunities and re-fires this trigger) from
            // causing an endless loop.
            if (current.FB_Open_Pipeline__c == pipeline
                && current.FB_Open_Opportunities__c == openCount) {
                continue;
            }

            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Pipeline__c = pipeline,
                FB_Open_Opportunities__c = openCount
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
