```apex
/**
 * LogPurgeJob
 *
 * Nightly purge job for integration logs stored in FB_Integration_Log__c.
 *
 * Retention policy:
 *  - Normal logs (Level__c is DEBUG / INFO / blank / anything other than ERROR)
 *    are deleted once they are more than 30 days old.
 *  - ERROR logs are retained much longer and are only deleted once they are
 *    more than 180 days old.
 *
 * The class is bulk safe: records are fetched and deleted in batches of 200
 * and deletes are performed with allOrNone = false, so a single failing record
 * never rolls back the whole purge.
 */
public with sharing class LogPurgeJob implements Schedulable {

    /** Name of the scheduled job as it appears in Setup -> Scheduled Jobs. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** Retention (in days) for logs whose Level__c is not ERROR. */
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** Retention (in days) for logs whose Level__c is ERROR. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Number of records processed per query/delete batch. */
    private static final Integer DELETE_BATCH_SIZE = 200;

    /** No-argument constructor (required for Schedulable / invocable Apex). */
    public LogPurgeJob() {
    }

    /**
     * Entry point invoked by the scheduler.
     */
    public void execute(SchedulableContext context) {
        purge(System.now());
    }

    /**
     * Schedules the purge job to run every day at 02:00 (in the time zone of
     * the user who schedules it) under the name 'Log purge (nightly)'.
     *
     * @return the Id of the scheduled job returned by System.schedule.
     */
    public static Id scheduleNightly() {
        CronTrigger cron = CronTrigger.schedule()
            .withHour(2)
            .withMinute(0)
            .withSecond(0);

        return System.schedule(JOB_NAME, cron, new LogPurgeJob());
    }

    /**
     * Deletes all log records that are eligible for purging.
     *
     * @param runTime reference point used to calculate the retention cut-offs.
     */
    private static void purge(Datetime runTime) {
        Datetime nonErrorCutoff = runTime.addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = runTime.addDays(-ERROR_RETENTION_DAYS);

        Integer totalDeleted = 0;
        Integer totalFailed = 0;

        while (true) {
            List<FB_Integration_Log__c> logs = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE CreatedDate < :nonErrorCutoff
                  AND (
                        Level__c = null
                     OR UPPER(Level__c) != 'ERROR'
                     OR CreatedDate < :errorCutoff
                  )
                LIMIT :DELETE_BATCH_SIZE
            ];

            if (logs.isEmpty()) {
                break;
            }

            List<Database.DeleteResult> results = Database.delete(logs, false);

            Integer deletedInBatch = 0;
            for (Database.DeleteResult result : results) {
                if (result.isSuccess()) {
                    deletedInBatch++;
                } else {
                    totalFailed++;
                    for (Database.Error err : result.getErrors()) {
                        System.debug(
                            LoggingLevel.ERROR,
                            'LogPurgeJob: could not delete log record - '
                                + err.getStatusCode()
                                + ': '
                                + err.getMessage()
                        );
                    }
                }
            }

            totalDeleted += deletedInBatch;

            // Safety net: if nothing could be deleted in this batch, stop to
            // avoid an endless loop (e.g. records that cannot be deleted).
            if (deletedInBatch == 0) {
                break;
            }
        }

        System.debug(
            LoggingLevel.INFO,
            'LogPurgeJob: deleted ' + totalDeleted + ' integration log record(s); '
                + totalFailed + ' failure(s).'
        );
    }
}
