/**
 * OpportunityRollupService
 *
 * Provides closed-won revenue rollups per Account for the current calendar year.
 *
 * Design notes:
 *  - The rollup is computed entirely in the database with a single aggregate SOQL
 *    query (SUM(...) GROUP BY AccountId). Individual Opportunity records are never
 *    loaded into heap, so the method stays bulk-safe and governor friendly.
 *  - The class is declared `with sharing`, so the aggregate query honours the
 *    running user's record sharing (and field/CRUD permissions).
 *  - Every requested Account Id is present in the returned map. Accounts with no
 *    qualifying opportunity, or whose qualifying opportunities all have a blank
 *    Amount, map to 0 (never null). Ids that were not requested are never keys.
 */
public with sharing class OpportunityRollupService {

    /**
     * Returns the sum of Amount over each requested account's won opportunities
     * whose CloseDate falls inside the current calendar year.
     *
     * @param accountIds Accounts to roll up. May be null or empty.
     * @return Map of Account Id to closed-won amount for the current calendar year.
     *         Always contains an entry (0 minimum) for every requested, non-null Id.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        // Guard: nothing requested -> nothing to compute.
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Work on a de-duplicated set with nulls removed.
        Set<Id> requestedIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                requestedIds.add(accountId);
            }
        }
        if (requestedIds.isEmpty()) {
            return result;
        }

        // Seed the map so every requested account has a key (default 0, never null).
        for (Id accountId : requestedIds) {
            result.put(accountId, 0);
        }

        // Current calendar year boundaries (CloseDate is a date-only field).
        Date today = Date.today();
        Integer currentYear = today.year();
        Date startOfYear = Date.newInstance(currentYear, 1, 1);
        Date endOfYear = Date.newInstance(currentYear, 12, 31);

        // Single aggregate query: sums are computed in the database.
        List<AggregateResult> rollupRows = [
            SELECT AccountId, SUM(Amount) wonAmount
            FROM Opportunity
            WHERE IsWon = true
                AND AccountId IN :requestedIds
                AND CloseDate >= :startOfYear
                AND CloseDate <= :endOfYear
            GROUP BY AccountId
        ];

        for (AggregateResult row : rollupRows) {
            Id accountId = (Id) row.get('AccountId');

            // Opportunities without an Account produce a null group - never a key.
            // Also defend against any row for an id that was not requested.
            if (accountId == null || !requestedIds.contains(accountId)) {
                continue;
            }

            // SUM ignores blank Amounts; if every Amount in the group is blank the
            // aggregate is null, which we normalise to 0.
            Decimal total = (Decimal) row.get('wonAmount');
            result.put(accountId, total == null ? 0 : total);
        }

        return result;
    }
}
