 * service are built in memory with fake ids produced by fflib_IDGenerator.
 */
@IsTest
public class OpportunityForecastServiceTest {
    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String STAGE_PROPOSAL = 'Proposal';

    /**
     * The weighted amount (Amount * Probability / 100, rounded to 2 decimals)
     * is summed per StageName over the opportunities returned by the selector.
     */
    @IsTest
    static void weightedAmountByStage_sumsWeightedAmountsPerStage() {
        Id accountOne = newAccountId();
        Id accountTwo = newAccountId();
        Set<Id> accountIds = new Set<Id>{ accountOne, accountTwo };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountOne, STAGE_PROSPECTING, new Decimal('1000.00'), new Decimal('50')),
            buildOpportunity(accountOne, STAGE_PROSPECTING, new Decimal('200.55'), new Decimal('33')),
            buildOpportunity(accountTwo, STAGE_QUALIFICATION, new Decimal('5000.00'), new Decimal('25')),
            buildOpportunity(accountTwo, STAGE_PROPOSAL, new Decimal('1200.00'), new Decimal('75'))
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock;
        mocks.startStubbing();
        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.areEqual(3, result.size(), 'One entry is expected for every stage that has opportunities');
        Assert.areEqual(new Decimal('566.18'), result.get(STAGE_PROSPECTING), '1000.00 * 50% + 200.55 * 33%');
        Assert.areEqual(new Decimal('1250.00'), result.get(STAGE_QUALIFICATION), '5000.00 * 25%');
        Assert.areEqual(new Decimal('900.00'), result.get(STAGE_PROPOSAL), '1200.00 * 75%');
