                },
                Contact.SObjectType => new List<Schema.SObjectField>{
                    Contact.Id,
                    Contact.FirstName,
                    Contact.LastName,
                    Contact.Email,
                    Contact.AccountId
                },
                Opportunity.SObjectType => new List<Schema.SObjectField>{
                    Opportunity.Id,
                    Opportunity.Name,
                    Opportunity.AccountId,
                    Opportunity.CloseDate,
                    Opportunity.StageName,
                    Opportunity.Amount,
                    Opportunity.Type
