/**
 * Domain class for Opportunity.
 *
 * Starts fulfilment whenever an Opportunity is won, i.e. when it is inserted as
 * 'Closed Won' or when its StageName changes to 'Closed Won' from any other stage.
 *
 * The fulfilment service is resolved through the Application Service Factory so that
 * it can be replaced by a mock in tests.
 */
public class Opportunities extends fflib_SObjectDomain {

    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Required by fflib_SObjectDomain so the domain can be instantiated reflectively
     * by the trigger handler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    public Opportunities(List<Opportunity> records) {
        super((List<SObject>) records);
    }

    /**
     * Opportunities inserted as 'Closed Won' qualify for fulfilment.
     */
    public override void afterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) getRecords()) {
            if (opportunity.StageName == CLOSED_WON) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    /**
     * Only opportunities whose stage actually changed to 'Closed Won' qualify.
     * Opportunities that were already 'Closed Won' are not qualified again.
     */
    public override void afterUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        Map<Id, Opportunity> oldRecords = (Trigger.oldMap == null)
            ? new Map<Id, Opportunity>()
            : (Map<Id, Opportunity>) Trigger.oldMap;

        for (Opportunity opportunity : (List<Opportunity>) getRecords()) {
            Opportunity oldOpportunity = oldRecords.get(opportunity.Id);
            String oldStageName = (oldOpportunity == null) ? null : oldOpportunity.StageName;

            if (opportunity.StageName == CLOSED_WON && oldStageName != CLOSED_WON) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    /**
     * Calls the fulfilment service at most once per trigger invocation,
     * and not at all when no opportunity qualifies.
     */
    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);

        fulfilmentService.startFulfilment(opportunityIds);
    }
}
