```apex
/**
 * Domain class for Opportunity.
 *
 * Encapsulates the business rules that are applied to Opportunity records
 * when they are created:
 *
 *  - CloseDate defaults to today + 30 days when it is not supplied
 *  - Type defaults to 'New Customer' when it is not supplied
 *
 * Values that are already populated are always left untouched, and the
 * defaults are applied on insert only (never on update).
 */
public with sharing class Opportunities extends fflib_SObjectDomain {

    /**
     * Standard fflib constructor hook.
     *
     * fflib_SObjectDomain.triggerHandler() uses this nested class to build the
     * domain object for the records handed over by the trigger, so the domain
     * can never be created without its records.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    /**
     * @param records The Opportunity records the domain operates on.
     */
    public Opportunities(List<SObject> records) {
        super(records);
    }

    /**
     * Applies the creation defaults.
     *
     * Only invoked for inserts, therefore records that already carry a value
     * (and all updates) are left as they are.
     */
    public override void beforeInsert() {
        for (SObject record : getRecords()) {
            Opportunity opportunity = (Opportunity) record;

            // Default the close date to 30 days from today when it was not supplied.
            if (opportunity.CloseDate == null) {
                opportunity.CloseDate = Date.today().addDays(30);
            }

            // Default the opportunity type when it was not supplied.
            if (String.isBlank(opportunity.Type)) {
                opportunity.Type = 'New Customer';
            }
        }
    }
}
