/**
 * Accounts domain.
 *
 * The domain is a plain collection class: it holds Account records, exposes
 * them in a typed fashion and contains the collection level business
 * operations. Trigger handling lives outside of the domain.
 *
 * Domains are always created through the Application.Domain factory so that
 * the factory (and any mock installed by unit tests) stays in control of how
 * the domain is built. The Set<Id> flavour of the factory loads the records
 * with the Accounts selector.
 */
public inherited sharing class Accounts extends fflib_SObjects implements IAccounts {

    /** Typed view of the records held by this domain. */
    private final List<Account> accountRecords;

    /**
     * Builds the domain through the Application.Domain factory.
     *
     * @param records the Accounts held by the domain
     * @return the domain built by the factory
     */
    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(
            Account.SObjectType,
            toSObjects(records)
        );
    }

    /**
     * Builds the domain through the Application.Domain factory. The factory
     * loads the records with the Accounts selector.
     *
     * @param accountIds the ids of the Accounts held by the domain
     * @return the domain built by the factory
     */
    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(
            Account.SObjectType,
            accountIds
        );
    }

    /**
     * Direct construction is reserved for the Application.Domain factory
     * (through the Constructor below) and for deriving new domains from an
     * existing one.
     *
     * @param records the records held by the domain
     */
    public Accounts(List<SObject> records) {
        super(records);
        this.accountRecords = toAccounts(records);
    }

    /**
     * Used by the Application.Domain factory to build Accounts instances.
     */
    public class Constructor {
        /**
         * @param records the records held by the domain
         * @return a new Accounts domain holding the given records
         */
        public Accounts construct(List<SObject> records) {
            return new Accounts(records);
        }
    }

    /**
     * @return the SObjectType handled by this domain
     */
    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * @return the name of the SObjectType handled by this domain
     */
    public String getType() {
        return 'Account';
    }

    /**
     * @return the Account records held by this domain
     */
    public List<Account> getAccounts() {
        return new List<Account>(accountRecords);
    }

    /**
     * Returns a new domain with the Accounts whose Rating equals the given
     * rating. This domain is not modified. When no record matches, an empty
     * domain is returned.
     *
     * @param rating the rating to filter on
     * @return a new domain holding the matching Accounts
     */
    public IAccounts selectByRating(String rating) {
        List<SObject> matching = new List<SObject>();
        for (Account account : accountRecords) {
            if (account.Rating == rating) {
                matching.add(account);
            }
        }
        return new Accounts(matching);
    }

    /**
     * @return the distinct, non null OwnerId values of the Accounts held by
     *         this domain
     */
    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account account : accountRecords) {
            if (account.OwnerId != null) {
                ownerIds.add(account.OwnerId);
            }
        }
        return ownerIds;
    }

    /**
     * Sets the Rating on every Account held by this domain.
     *
     * @param rating the rating to apply
     */
    public void setRating(String rating) {
        for (Account account : accountRecords) {
            account.Rating = rating;
        }
    }

    /**
     * @param records the Accounts to convert
     * @return the same records as a List<SObject>
     */
    private static List<SObject> toSObjects(List<Account> records) {
        List<SObject> result = new List<SObject>();
        if (records != null) {
            for (Account account : records) {
                result.add(account);
            }
        }
        return result;
    }

    /**
     * @param records the records to convert
     * @return the same records as a List<Account>
     */
    private static List<Account> toAccounts(List<SObject> records) {
        List<Account> result = new List<Account>();
        if (records != null) {
            for (SObject record : records) {
                result.add((Account) record);
            }
        }
        return result;
    }
}
