/**
 * Selector for Opportunity.
 *
 * Follows the fflib (fflib-apex-common) selector pattern: every query is built from a
 * query factory that applies this selector's field list and security settings, so the
 * field list and the security behaviour can never drift away from the selector.
 */
public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {

    /** Relationship path used to read the parent account's Name, e.g. `Account.Name`. */
    private static final String ACCOUNT_NAME_PATH = 'Account.Name';

    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities of the given accounts.
     *
     * Ordering:
     *   1. Amount descending (opportunities without an Amount are returned last),
     *   2. CloseDate ascending (earliest first) for equal Amounts.
     *
     * At most `maxRecords` opportunities are returned and the whole result set is
     * retrieved with a single query.
     *
     * @param accountIds the accounts whose open opportunities should be returned
     * @param maxRecords the maximum number of opportunities to return
     * @return the matching opportunities, never null
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard clauses: no query is executed for an empty request.
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // NOTE: a dedicated query factory is used on purpose. The selector's shared
        // factory must not be mutated, otherwise the condition/ordering/limit applied
        // here would also leak into the other methods of this selector (e.g. selectById,
        // which keeps its default ordering by opportunity Name). The selector's own
        // field list and security settings are applied explicitly below.
        fflib_QueryFactory oppQueryFactory = new fflib_QueryFactory(getSObjectType())
            .selectFields(getSObjectFieldList())
            .withSecurityEnforced()
            .withCondition('AccountId IN :accountIds AND IsClosed = false')
            .withOrdering('Amount DESC NULLS LAST, CloseDate ASC')
            .withLimit(maxRecords);

        // The parent account's Name is added to the SELECT list so that callers can use
        // `oppportunity.Account.Name` without an extra query.
        String soql = addParentAccountName(oppQueryFactory.toString());

        return (List<Opportunity>) Database.query(soql);
    }

    /**
     * Adds the parent account's Name (`Account.Name`) to the SELECT clause of the query
     * that was built by the query factory.
     *
     * @param soql the query built by the query factory
     * @return the query including the parent account's Name in its SELECT clause
     */
    private static String addParentAccountName(String soql) {
        Integer selectIndex = soql.indexOf('SELECT');
        Integer fromIndex = soql.indexOf(' FROM ');

        // Defensive: if the query cannot be parsed, return it untouched.
        if (selectIndex < 0 || fromIndex < 0 || fromIndex <= selectIndex) {
            return soql;
        }

        String selectClause = soql.substring(selectIndex + 'SELECT'.length(), fromIndex);
        if (!selectClause.toLowerCase().contains(ACCOUNT_NAME_PATH.toLowerCase())) {
            selectClause = selectClause + ', ' + ACCOUNT_NAME_PATH;
        }

        return soql.substring(0, selectIndex + 'SELECT'.length())
            + selectClause
            + soql.substring(fromIndex);
    }
}
