/**
 * CasePriorityHandler
 *
 * Raises the priority of cases belonging to "Hot" accounts so that tickets from
 * our most important customers jump the queue.
 *
 * Rules:
 *  - Account.Rating = 'Hot'  -> Case.Priority = 'High'
 *  - Anything else            -> the Case keeps the Priority it was created with
 *                                (this includes cases that have no Account).
 *
 * The handler is bulk-safe: it is written for a list of cases and performs a
 * single SOQL query for the whole batch, never a query inside the loop.
 */
public class CasePriorityHandler {

    /** Account.Rating value that qualifies for a priority bump. */
    private static final String HOT_RATING = 'Hot';

    /** Case.Priority picklist value applied to qualifying cases. */
    private static final String HIGH_PRIORITY = 'High';

    /**
     * Sets Priority = 'High' on cases whose account is rated 'Hot'.
     * All other cases are left untouched.
     *
     * @param newCases the cases being inserted (may be null or empty)
     */
    public static void setPriority(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        // 1. Collect the distinct account ids of the batch (cases without an
        //    account are skipped - they keep their original priority).
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            // Nothing to evaluate; every case keeps its original priority.
            return;
        }

        // 2. One single SOQL query for the entire batch.
        Map<Id, String> ratingByAccountId = new Map<Id, String>();
        for (Account a : [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]) {
            ratingByAccountId.put(a.Id, a.Rating);
        }

        // 3. Apply the priority only to cases on a 'Hot' account.
        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }
            String rating = ratingByAccountId.get(c.AccountId);
            if (rating != null && HOT_RATING.equals(rating)) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }
}
