/**
 * Publishes {@code Deal_Stage_Change__e} platform events (one per Opportunity).
 *
 * Design notes
 * ------------
 * - One platform event is published per Opportunity:
 *     Opportunity_Id__c = Opportunity.Id        (Text 18)
 *     Stage__c           = Opportunity.StageName (Text 40)
 *     Amount__c          = Opportunity.Amount    (Number 16,2)
 * - The whole batch is published with a SINGLE {@code EventBus.publish()} call.
 *   Publishing one event at a time consumes one DML statement per call (150 per transaction
 *   limit), so a 200 record trigger batch would fail with
 *   "System.LimitException: Too many DML statements: 151" half way through, leaving a
 *   partially published batch behind (platform event publishes are not rolled back).
 *   A batched publish costs 1 DML statement + 1 DML row per event.
 * - {@code EventBus.publish()} returns one Database.SaveResult per published event, in the
 *   same order as the events handed in, so the caller can still tell exactly which
 *   Opportunity/event failed (identical information to a per record publish loop).
 * - The event is delivered with "Publish After Commit" subscriber behaviour, so subscribers
 *   only see the events after the Opportunity transaction commits.
 * - Fatal publish problems (invalid event type, missing access, ...) surface as
 *   {@code EventBusException}; they are deliberately not swallowed here.
 */
public with sharing class DealEventPublisher {

    /** Raised when the batch cannot be turned into valid platform events. */
    public class PublishException extends Exception {}

    /** Utility class - not instantiable. */
    private DealEventPublisher() {}

    /**
     * Publishes one {@code Deal_Stage_Change__e} event per Opportunity.
     *
     * @param opportunities Opportunities to publish; every element must be a persisted record.
     * @return one Database.SaveResult per Opportunity, in the same order as the input list.
     *         An empty (or null) input publishes nothing and returns an empty list.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        // Nothing to do: no publish call, no DML consumed.
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opportunity : opportunities) {
            // A platform event without the 18 character Opportunity Id is meaningless.
            // Skipping it would also misalign the returned results, so fail fast.
            if (opportunity == null || opportunity.Id == null) {
                throw new PublishException(
                    'Deal_Stage_Change__e requires a persisted Opportunity Id.'
                );
            }

            events.add(
                new Deal_Stage_Change__e(
                    Opportunity_Id__c = opportunity.Id,
                    Stage__c = opportunity.StageName,
                    Amount__c = opportunity.Amount
                )
            );
        }

        // One publish call for the whole batch:
        // 1 DML statement + 1 DML row per event (safe for the 200 record trigger batch).
        List<Database.SaveResult> publishResults = EventBus.publish(events);

        // Defensive: the platform returns one SaveResult per event, in submission order.
        if (publishResults == null || publishResults.size() != events.size()) {
            throw new PublishException(
                'Unexpected publish result count: expected ' + events.size() +
                ' but received ' + (publishResults == null ? 0 : publishResults.size()) + '.'
            );
        }

        for (Database.SaveResult publishResult : publishResults) {
            results.add(publishResult);
        }

        return results;
    }
}
