/**
 * Applies the standard discount to Opportunity Line Items that were saved without one.
 *
 * The discount rules themselves live in PricingRules (owned by the pricing team);
 * this class never re-implements them, it only resolves the product -> family mapping
 * in bulk and delegates the rule evaluation to PricingRules.
 */
public with sharing class LineItemDiscountHandler {
    /**
     * For every line in the batch whose Discount is null, set the standard discount
     * for the line's product. Lines that already have a Discount (including 0) keep it.
     *
     * @param lines Batch of Opportunity Line Items (Trigger.new in a before insert trigger).
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        if (lines == null || lines.isEmpty()) {
            return;
        }

        // 1) Collect the distinct products we actually need to price (one query for the batch).
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            // Every line already has a discount, or none of them reference a product.
            return;
        }

        Map<Id, String> familyByProductId = new Map<Id, String>();
        for (Product2 product : [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]) {
            familyByProductId.put(product.Id, product.Family);
        }

        // 2) Apply the standard discount where the rep did not enter one.
        for (OpportunityLineItem line : lines) {
            if (line.Discount != null) {
                // Rep supplied a discount (0 included) - keep it.
                continue;
            }

            if (line.Product2Id == null) {
                // No product on the line, so there is no standard discount to apply.
                continue;
            }

            if (!familyByProductId.containsKey(line.Product2Id)) {
                // Product not found (deleted, or not visible to the running user):
                // leave the discount untouched rather than failing the whole quote.
                continue;
            }

            // Single source of truth for the discount rules.
            line.Discount = PricingRules.standardDiscountForFamily(familyByProductId.get(line.Product2Id));
        }
    }
}
