/**
 * CaseTrigger
 * ---------------------------------------------------------------------------
 * Fires after a Case is updated and queues a CSAT survey task for every case
 * that has just been closed (open -> closed) and that has a contact.
 *
 * Design notes
 *  - The trigger contains no DML and no SOQL. It only reads Trigger.new /
 *    Trigger.oldMap and hands the work over to Queueable Apex, so a bulk close
 *    (list-view mass close or a nightly API batch of up to 200 cases) can never
 *    hit governor limits in the user's transaction.
 *  - One job per case: every case is processed in its own transaction, so a
 *    single failure can never affect the other cases.
 *  - The platform only allows 50 asynchronous jobs to be queued per transaction.
 *    The trigger therefore queues at most 49 per-case jobs plus one continuation
 *    job (a *different* job type, so it can be queued in the same transaction);
 *    the continuation job queues the remainder in the next transaction.
 *  - Cases without a contact are ignored - no survey task is created for them.
 */
trigger CaseTrigger on Case (after update) {

    // Platform limit: maximum number of async jobs that can be queued in one transaction.
    Integer maxJobsPerTransaction = 50;

    // ------------------------------------------------------------------
    // 1. Collect the cases that were just closed and that have a contact.
    // ------------------------------------------------------------------
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);

        // Only a genuine open -> closed transition (not a re-save of an
        // already closed case, and not a reopen).
        if (oldCase == null || oldCase.IsClosed || !newCase.IsClosed) {
            continue;
        }

        // No contact -> nobody to survey, so no task.
        if (newCase.ContactId == null) {
            continue;
        }

        newlyClosedCaseIds.add(newCase.Id);
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    // ------------------------------------------------------------------
    // 2. Queue one job per case, in chunks that respect the 50 job limit.
    // ------------------------------------------------------------------
    Integer offset = 0;

    while (offset < newlyClosedCaseIds.size()) {
        Integer chunkSize = newlyClosedCaseIds.size() - offset;
        if (chunkSize > maxJobsPerTransaction) {
            chunkSize = maxJobsPerTransaction;
        }

        Boolean moreToCome = (offset + chunkSize) < newlyClosedCaseIds.size();
        if (moreToCome) {
            // Leave one slot in this transaction for the continuation job.
            chunkSize -= 1;
        }

        List<Id> chunk = newlyClosedCaseIds.subList(offset, offset + chunkSize);

        // One job per case -> one transaction (and one failure domain) per case.
        for (Id caseId : chunk) {
            System.enqueueJob(new CaseSurveyJob(caseId));
        }

        offset += chunkSize;

        if (moreToCome) {
            // More cases than this transaction may queue: hand the remainder to a
            // continuation job, which queues them in the next transaction.
            List<Id> remainingCaseIds = new List<Id>(
                newlyClosedCaseIds.subList(offset, newlyClosedCaseIds.size())
            );
            System.enqueueJob(new CaseSurveyJob.Continuation(remainingCaseIds));
        }
    }
}
