import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const ACCOUNT_FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    /** Supplied by the Lightning record page (or set imperatively). */
    @api recordId;

    /** The Account record returned by Lightning Data Service. */
    record;

    /** The error returned by Lightning Data Service, if any. */
    error;

    @wire(getRecord, { recordId: '$recordId', fields: ACCOUNT_FIELDS })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.record = undefined;
            this.error = error;
        } else {
            // Either the very first call (nothing loaded yet) or the parameters
            // just changed (new recordId). Drop any stale data so the UI shows
            // the spinner while the new record is being fetched.
            this.record = undefined;
            this.error = undefined;
        }
    }

    /** True while there is nothing to show and nothing went wrong. */
    get isLoading() {
        if (this.error) {
            return false;
        }
        if (!this.record) {
            return true;
        }
        // Guard against a stale record when recordId changes in a reused tab.
        return this.record.id !== this.recordId;
    }

    get hasError() {
        return !!this.error;
    }

    get hasRecord() {
        return !!this.record && !this.error;
    }

    get accountName() {
        return this.record?.fields?.Name?.value;
    }

    /** Undefined/empty when the account has no industry (paragraph is skipped). */
    get industry() {
        const value = this.record?.fields?.Industry?.value;
        return value ? value : undefined;
    }

    /** Annual revenue formatted as currency; undefined when the field is empty. */
    get revenue() {
        const value = this.record?.fields?.AnnualRevenue?.value;
        return value === null || value === undefined ? undefined : value;
    }

    /** Owner's name from the referenced User record. */
    get ownerName() {
        const owner = this.record?.fields?.Owner?.value;
        if (!owner) {
            return undefined;
        }
        // Requested sub-field shape: { id, fields: { Name: { value } } }
        if (owner.fields && owner.fields.Name) {
            return owner.fields.Name.value;
        }
        // Flat shape: { Name: '...' }
        return owner.Name;
    }

    /** Message to display when the wire returns an error. */
    get errorMessage() {
        return this.error?.body?.message;
    }
}
