import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

/**
 * Account quick links.
 *
 * - New Contact (account prefilled)
 * - Related Contacts list for the account
 * - Edit the account
 * - Link to the "My_Open_Cases" Case list view
 *
 * All navigation is performed with the Lightning navigation service.
 */
export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    /** Id of the account the component is displayed on. */
    @api recordId;

    /** Resolved URL of the Case list view "My_Open_Cases" (empty until generated). */
    casesUrl;

    connectedCallback() {
        // Build the URL for the Case list view "My_Open_Cases".
        // GenerateUrl is asynchronous, so the link is rendered only once resolved.
        this[NavigationMixin.GenerateUrl]({
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        })
            .then((url) => {
                this.casesUrl = url;
            })
            .catch((error) => {
                this.casesUrl = undefined;
                // eslint-disable-next-line no-console
                console.error('Error generating the "My_Open_Cases" list view URL.', error);
            });
    }

