import { LightningElement } from 'lwc';

/**
 * Module-scoped counter used to generate a unique DOM id for every
 * <c-collapsible-section> instance on the page.
 *
 * The id is applied to the collapsible region and referenced by the toggle
 * button's `aria-controls` attribute. Ids must be unique per *document*
 * (not per component), so a simple counter is used instead of a hard-coded
 * value. It is incremented once per component instance.
 */
let instanceCounter = 0;

export default class CollapsibleSection extends LightningElement {
    /** Unique id of the collapsible body; the target of the button's aria-controls. */
    bodyId;

    /** True when the body is visible. The section always starts collapsed. */
    isExpanded = false;

    constructor() {
        super();
        instanceCounter += 1;
        this.bodyId = `collapsible-section-body-${instanceCounter}`;
    }

    /**
     * Value rendered on the toggle button's `aria-expanded` attribute.
     * Returned as an explicit string so the attribute is always present and
     * holds either "true" or "false" (never an empty string or a boolean).
     */
    get expandedState() {
        return this.isExpanded ? 'true' : 'false';
    }

    /**
     * Controls the `hidden` attribute of the section body.
     *
     * - `true`      -> the `hidden` attribute is rendered, so the region is
     *                  hidden visually and removed from the accessibility tree.
     * - `undefined` -> the attribute is removed entirely, so the region is
     *                  visible and exposed to assistive technology.
     *
     * Returning `undefined` (rather than `false`) guarantees the attribute is
     * removed, no matter how the template compiler treats the `hidden`
     * attribute: a stringified "false" would still be *present* and would
     * therefore hide the content.
     */
    get bodyHidden() {
        return this.isExpanded ? undefined : true;
    }

    /**
     * Click handler for the native toggle button.
     * A native <button> already provides Enter/Space activation and focus,
     * so no extra keyboard handling is required.
     */
    handleToggle() {
        this.isExpanded = !this.isExpanded;
    }
}
