import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    // Private backing store for the public `contacts` property.
    // Always an array, so the template never has to deal with undefined/null.
    _contacts = [];

    /**
     * Public property: array of `{ Id, Name, Title }` objects.
     * The parent owns the array; this component never mutates it.
     */
    @api
    get contacts() {
        return this._contacts;
    }

    set contacts(value) {
        // Normalize defensively: undefined, null or a non-array means "no contacts".
        this._contacts = Array.isArray(value) ? value : [];
    }

    /** True when there is at least one contact to render. */
    get hasContacts() {
        return this._contacts.length > 0;
    }

    /** Contacts sorted by Name (ascending) using localeCompare. A copy is sorted so the parent's array is not mutated. */
    get sortedContacts() {
        return [...this._contacts].sort((a, b) => {
            const nameA = a && a.Name != null ? String(a.Name) : '';
            const nameB = b && b.Name != null ? String(b.Name) : '';
            return nameA.localeCompare(nameB);
        });
    }

    /** e.g. "1 contact" or "3 contacts". */
    get countLabel() {
        const count = this._contacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }
}
