```js
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;
const DEFAULT_ERROR_MESSAGE = 'An unknown error occurred. Please try again.';

export default class ContactSearch extends LightningElement {
    /** Raw value as typed by the user (kept untrimmed for display purposes). */
    searchTerm = '';
    /** Contacts returned by the most recent (and still valid) search. */
    contacts = [];
    /** Message rendered inside <p class="error">. */
    errorMessage;

    /** Handle of the pending debounce timer, if any. */
    searchTimeoutId;
    /** Monotonic counter used to discard out-of-order / stale responses. */
    latestRequestId = 0;
    /** Tracks component lifecycle so a removed component never renders results. */
    isComponentConnected = false;

    connectedCallback() {
        this.isComponentConnected = true;
    }

    disconnectedCallback() {
        this.isComponentConnected = false;
        this.cancelPendingSearch();
        // Invalidate any in-flight request: a late response must not touch the DOM.
        this.latestRequestId += 1;
    }

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    /**
     * `change` fires on every keystroke for this input, so every keystroke
     * restarts the debounce window.
     */
    handleChange(event) {
        const rawValue =
            event && event.target && event.target.value !== undefined && event.target.value !== null
                ? String(event.target.value)
                : '';
        this.searchTerm = rawValue;

        const searchTerm = rawValue.trim();

        // Always drop the previously scheduled call: only the latest value matters.
        this.cancelPendingSearch();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            // Nothing to search for: cancel pending work, ignore in-flight
            // responses and clear whatever is currently displayed.
            this.latestRequestId += 1;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        this.searchTimeoutId = setTimeout(() => {
            this.searchTimeoutId = undefined;
            if (!this.isComponentConnected) {
                return;
            }
            this.executeSearch(searchTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    cancelPendingSearch() {
        if (this.searchTimeoutId !== undefined && this.searchTimeoutId !== null) {
            clearTimeout(this.searchTimeoutId);
            this.searchTimeoutId = undefined;
        }
    }

    async executeSearch(searchTerm) {
        // Capture the id of *this* request so responses can be matched against it.
        const requestId = ++this.latestRequestId;
        this.errorMessage = undefined;

        try {
            const results = await searchContacts({ searchTerm });

            // Ignore stale (out-of-order) responses and responses that arrive
            // after the component has been removed from the page.
            if (!this.isComponentConnected || requestId !== this.latestRequestId) {
                return;
            }

            this.contacts = Array.isArray(results) ? results : [];
        } catch (error) {
            if (!this.isComponentConnected || requestId !== this.latestRequestId) {
                return;
            }

            this.contacts = [];
            this.errorMessage = this.extractErrorMessage(error);
        }
    }

    extractErrorMessage(error) {
        if (error) {
            if (error.body && error.body.message) {
                return error.body.message;
            }
            if (Array.isArray(error.body) && error.body.length && error.body[0].message) {
                return error.body[0].message;
            }
            if (error.message) {
                return error.message;
            }
        }
        return DEFAULT_ERROR_MESSAGE;
    }
}
