import { LightningElement, api, track } from 'lwc';

import ADD_LABEL from '@salesforce/label/c.Favorite_Add';
import REMOVE_LABEL from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle button that marks a record as a favourite.
 *
 * The parent owns the `favorite` public property and can push a new value at
 * any time (for example after a server refresh). The component keeps an
 * internal copy of that value so that a click can update the UI optimistically
 * while still following every real change that comes from the parent.
 *
 * @fires favoritechange {detail: {favorite: boolean}}
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Last value received from the parent through the `favorite` public property.
     * Used to tell a real change apart from a repeated value.
     * @type {boolean}
     */
    _parentFavorite = false;

    /**
     * Value currently rendered by the button. It can be ahead of the parent
     * value while an optimistic update is waiting for the server response.
     * @type {boolean}
     */
    @track isFavorite = false;

    /**
     * Public property set by the parent.
     * @type {boolean}
     */
    @api
    get favorite() {
        return this.isFavorite;
    }

    set favorite(value) {
        const nextValue = Boolean(value);

        // Only react to an actual change of the value coming from the parent:
        // a parent re-render that repeats the same value must not roll back an
        // optimistic update that is still waiting for the server response.
        if (nextValue !== this._parentFavorite) {
            this._parentFavorite = nextValue;
            this.isFavorite = nextValue;
        }
    }

    /**
     * ARIA pressed state of the toggle button.
     * @returns {string} 'true' when the record is a favourite, 'false' otherwise.
     */
    get pressedAttribute() {
        return this.isFavorite ? 'true' : 'false';
    }

    /**
     * Label of the action that a click performs.
     * @returns {string} Custom label of the add or remove action.
     */
    get actionLabel() {
        return this.isFavorite ? REMOVE_LABEL : ADD_LABEL;
    }

    /**
     * Fill of the star icon: filled when the record is a favourite.
     * @returns {string} SVG fill value.
     */
    get iconFill() {
        return this.isFavorite ? 'currentColor' : 'none';
    }

    /**
     * Flips the state optimistically and notifies the parent.
     * @returns {void}
     */
    handleClick() {
        const newValue = !this.isFavorite;

        // Optimistic update: show the new state right away.
        this.isFavorite = newValue;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: newValue },
                bubbles: true,
                composed: true
            })
        );
    }
}
