import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    MessageContext,
    APPLICATION_SCOPE
} from 'lightning/messageService';

const ACCOUNT_SELECTED_CHANNEL = 'Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    /** Id of the account currently selected; null when nothing is selected. */
    accountId = null;

    /** Message context supplied by the platform (needed to subscribe/publish). */
    messageContext;

    /** The single active subscription held by this component instance. */
    subscription;

    /**
     * The message context is delivered asynchronously, so the subscription is
     * (re)established from the wire callback as soon as the context is known.
     * The subscription is created with APPLICATION_SCOPE because the publisher
     * lives in the utility bar, outside of the app page component tree.
     */
    @wire(MessageContext)
    wiredMessageContext(messageContext) {
        this.messageContext = messageContext;
        this.subscribeToAccountSelected();
    }

    connectedCallback() {
        // Re-inserted component instance: (re)subscribe exactly once.
        this.subscribeToAccountSelected();
    }

    disconnectedCallback() {
        // Component removed from the page (tab closed, navigation, ...):
        // release the subscription so nothing is left behind and so that a
        // later re-insertion can subscribe again.
        this.unsubscribeFromAccountSelected();
    }

    subscribeToAccountSelected() {
        // Never hold more than one subscription.
        if (this.subscription || !this.messageContext) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            this.handleAccountSelected,
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromAccountSelected() {
        if (!this.subscription) {
            return;
        }
        const subscription = this.subscription;
        // Clear first so a later connectedCallback() can subscribe again.
        this.subscription = undefined;
        try {
            // APPLICATION_SCOPE subscriptions are released with the
            // subscription reference alone.
            unsubscribe(subscription);
        } catch (error) {
            // Fallback for platforms that expect the full signature.
            unsubscribe(this.messageContext, subscription, ACCOUNT_SELECTED_CHANNEL);
        }
    }

    handleAccountSelected = (message) => {
        this.accountId = message && message.recordId ? message.recordId : null;
    };

    handleClearSelection = () => {
        // Clear locally right away; the panel also receives its own message.
        this.accountId = null;
        if (!this.messageContext) {
            return;
        }
        publish(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            { recordId: null },
            { scope: APPLICATION_SCOPE }
        );
    };
}
