import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    /** Account Id provided by the record page (LightningRecordPage / *.html-meta.xml). */
    @api recordId;

    opportunities = [];
    errorMessage = '';
    hasError = false;
    isLoading = false;
    hasLoaded = false;

    connectedCallback() {
        // Imperative call, exactly once, when the component is inserted.
        // Guard against a second connectedCallback (e.g. DOM re-parenting).
        if (!this.hasLoaded) {
            this.hasLoaded = true;
            this.loadOpportunities();
        }
    }

    get hasOpportunities() {
        return Array.isArray(this.opportunities) && this.opportunities.length > 0;
    }

    loadOpportunities() {
        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = '';

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result ? result : [];
                this.hasError = false;
                this.errorMessage = '';
            })
            .catch((error) => {
                this.opportunities = [];
                this.errorMessage = this.extractErrorMessage(error);
                this.hasError = true;
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    handleRetry() {
        this.loadOpportunities();
    }

    extractErrorMessage(error) {
        if (error) {
            if (error.body) {
                if (Array.isArray(error.body.message)) {
                    return error.body.message.join(', ');
                }
                if (error.body.message) {
                    return error.body.message;
                }
                if (Array.isArray(error.body.pageErrors) && error.body.pageErrors.length > 0) {
                    return error.body.pageErrors.map((pageError) => pageError.message).join(', ');
                }
            }
            if (error.message) {
                return error.message;
            }
        }
        return 'An unknown error occurred while loading opportunities.';
    }
}
