```javascript
import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /**
     * Lines to edit.
     * @type {Array<{key: string, productName: string, quantity: number}>}
     */
    @api lines = [];

    /** Renders the "Fix the highlighted lines." message. */
    showError = false;

    /** True when there is at least one line to render. */
    get hasLines() {
        return Array.isArray(this.lines) && this.lines.length > 0;
    }

    /**
     * All rendered line editors, in display order.
     * querySelectorAll returns elements in document order, which matches the
     * order the lines were rendered in by the for:each directive.
     * @returns {Array<Element>}
     */
    get lineEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    /**
     * Single handler for the action buttons; the behaviour is selected with
     * the data-action attribute on the button.
     * @param {Event} event
     */
    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.resetAll();
        } else if (action === 'submit') {
            this.submitAll();
        }
    }

    /** Resets every line editor back to its default value. */
    resetAll() {
        this.lineEditors.forEach((editor) => {
            editor.reset();
        });
    }

    /**
     * Validates every line editor and, when all of them are valid, dispatches
     * the submit event with the current values.
     */
    submitAll() {
        const editors = this.lineEditors;

        // Validate EVERY editor, even after one has already reported a problem,
        // so that all invalid lines show their error message at once.
        let allValid = true;
        editors.forEach((editor) => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        const values = editors.map((editor) => editor.getValue());

        this.showError = false;
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines: values },
                bubbles: true,
                composed: true
            })
        );
    }
}
