```js
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    // Rendered values
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasStats = false;

    // Internal state
    _pollTimerId = null;
    _visibilityHandler = null;
    _requestInFlight = false;
    _generation = 0;
    _isConnected = false;

    connectedCallback() {
        this._isConnected = true;
        // Bump the generation so results of any request started before this
        // connection are ignored (guards against stale writes on re-insert).
        this._generation += 1;

        // Single listener, registered on every (re)connection.
        this._visibilityHandler = this._handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._visibilityHandler);

        // One and only one polling loop.
        this._startPolling();

        // Load immediately on insertion.
        this._loadStats();
    }

    disconnectedCallback() {
        this._isConnected = false;
        this._generation += 1; // invalidate any in-flight response
        this._requestInFlight = false;

        this._stopPolling();

        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
    }

    // ---------------------------------------------------------------------
    // Polling
    // ---------------------------------------------------------------------
    _startPolling() {
        this._stopPolling(); // never run two loops at once
        this._pollTimerId = window.setInterval(() => {
            this._poll();
        }, REFRESH_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._pollTimerId !== null && this._pollTimerId !== undefined) {
            window.clearInterval(this._pollTimerId);
            this._pollTimerId = null;
        }
    }

    _poll() {
        if (!this._isConnected) {
            return;
        }
        // Background tabs: never hit Apex while the page is hidden.
        if (document.visibilityState !== 'visible') {
            return;
        }
        this._loadStats();
    }

    // ---------------------------------------------------------------------
    // Visibility handling
    // ---------------------------------------------------------------------
    _handleVisibilityChange() {
        if (!this._isConnected) {
            return;
        }
        if (document.visibilityState === 'visible') {
            // Page came back to the foreground: refresh right away and
            // keep the existing 60 second loop running.
            this._loadStats();
        }
    }

    // ---------------------------------------------------------------------
    // Data access
    // ---------------------------------------------------------------------
    _loadStats() {
        if (!this._isConnected) {
            return;
        }
        // No requests while the page is hidden.
        if (document.visibilityState !== 'visible') {
            return;
        }
        // Skip this refresh if the previous request is still running.
        if (this._requestInFlight) {
            return;
        }

        const generation = this._generation;
        this._requestInFlight = true;

        getQueueStats()
            .then((result) => {
                this._requestInFlight = false;
                if (!this._isConnected || generation !== this._generation) {
                    return; // component was removed / re-created meanwhile
                }
                this.waiting = result ? result.waiting : 0;
                this.longestWaitMinutes = result ? result.longestWaitMinutes : 0;
                this.hasStats = true;
                this.errorMessage = undefined; // clear previous error
            })
            .catch((error) => {
                this._requestInFlight = false;
                if (!this._isConnected || generation !== this._generation) {
                    return;
                }
                this.errorMessage = this._extractErrorMessage(error);
                // Keep polling: the next successful refresh clears the error.
            });
    }

    _extractErrorMessage(error) {
        const body = error && error.body;
        if (body && body.message) {
            return Array.isArray(body.message) ? body.message.join(', ') : body.message;
        }
        return 'Unable to load queue statistics.';
    }
}
