import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

// Personal / free-mail providers that are not accepted for event registration.
const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    // Current value of every field, kept from each input's `change` event.
    fields = { fullName: '', email: '', company: '' };

    // True while the Apex call is in flight.
    isRegistering = false;

    get fullName() {
        return this.fields.fullName;
    }

    get email() {
        return this.fields.email;
    }

    get company() {
        return this.fields.company;
    }

    get emailInput() {
        return this.template.querySelector('lightning-input[data-field="email"]');
    }

    get inputs() {
        return Array.from(this.template.querySelectorAll('lightning-input'));
    }

    handleChange(event) {
        const field = event.target.dataset.field;
        if (!field) {
            return;
        }
        this.fields = { ...this.fields, [field]: event.detail.value };
    }

    handleRegister() {
        if (this.isRegistering) {
            return;
        }

        // 1. Work-email check first: set (or clear) the custom validity message
        //    on the email input BEFORE any reportValidity() call.
        const emailInput = this.emailInput;
        if (emailInput) {
            const domain = this.getEmailDomain(this.fields.email);
            if (FREE_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // 2. Report on EVERY input so all invalid fields show their messages at
        //    once. `map` is used deliberately (not `every`/`some`) because those
        //    short-circuit and would skip the remaining inputs.
        const validityResults = this.inputs.map((input) => input.reportValidity());

        // 3. Stop if anything is invalid.
        if (!validityResults.every((isValid) => isValid === true)) {
            return;
        }

        // 4. Submit imperatively to Apex.
        this.isRegistering = true;
        register({
            fullName: this.fields.fullName,
            email: this.fields.email,
            company: this.fields.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error && error.body ? error.body.message : undefined
                    })
                );
            })
            .finally(() => {
                this.isRegistering = false;
            });
    }

    getEmailDomain(email) {
        if (!email || typeof email !== 'string') {
            return '';
        }
        const parts = email.trim().toLowerCase().split('@');
        return parts.length > 1 ? parts[parts.length - 1].trim() : '';
    }
}
