import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // -----------------------------------------------------------------------
    // Public API
    // -----------------------------------------------------------------------

    /**
     * Display only heading.
     * It is stored exactly as the parent supplied it (never upper cased in
     * place), so the parent's own value stays untouched. Because it is a
     * reactive public property, later changes made by the parent are rendered
     * as well.
     */
    @api heading;

    /**
     * The task list supplied by the parent.
     * The parent's array and its task objects are never mutated: the component
     * renders and edits its own copy (`items`). When the parent passes a new
     * array, the rendered list is replaced by a copy of it.
     */
    _tasks = [];

    // -----------------------------------------------------------------------
    // Internal state
    // -----------------------------------------------------------------------

    /** Working copy of the task list that is rendered and edited. */
    items = [];

    /** Value currently held by the `new-task` input. */
    newLabel = '';

    /** Sequence used to build unique ids for newly added tasks. */
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        this.copyTasks();
    }

    connectedCallback() {
        // The parent may never supply a value -> start with an empty list.
        if (!Array.isArray(this._tasks)) {
            this._tasks = [];
        }
        this.copyTasks();
    }

    // -----------------------------------------------------------------------
    // Derived values
    // -----------------------------------------------------------------------

    /** Upper cased heading used for display only. */
    get headingText() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    /** Number of tasks that are not done yet. */
    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    /**
     * Replaces the rendered list with a copy of the parent's list.
     * The parent's array and task objects are left untouched.
     */
    copyTasks() {
        const source = Array.isArray(this._tasks) ? this._tasks : [];
        this.items = source.map((task) => ({
            id: task.id,
            label: task.label,
            done: task.done === true
        }));
    }

    /** Builds an id that is not used by any of the current tasks. */
    generateId() {
        let id;
        do {
            id = `task-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));
        return id;
    }

    /**
     * Reads the label that is currently held by the `new-task` input.
     * The committed value (`change` event) is used as a fallback in case the
     * input has not emitted its change event yet.
     */
    readNewTaskLabel() {
        const input = this.template.querySelector('lightning-input.new-task');
        const fromInput = input && typeof input.value === 'string' ? input.value : '';
        const raw = fromInput.trim() ? fromInput : this.newLabel || '';
        return String(raw).trim();
    }

    /** Empties the `new-task` input. */
    clearNewTaskInput() {
        this.newLabel = '';
        const input = this.template.querySelector('lightning-input.new-task');
        if (!input) {
            return;
        }
        input.value = '';
        // `lightning-input` does not always keep its internal value in sync
        // while the user types, so the native input it owns is cleared too.
        const nativeInput = this.findNativeInput(input);
        if (nativeInput) {
            nativeInput.value = '';
        }
    }

    /** Finds the native `input` element rendered by a `lightning-input`. */
    findNativeInput(input) {
        const candidates = [];
        if (input.shadowRoot) {
            candidates.push(input.shadowRoot.querySelector('input'));
        }
        candidates.push(input.querySelector('input'));
        return candidates.find((element) => !!element);
    }

    // -----------------------------------------------------------------------
    // Event handlers
    // -----------------------------------------------------------------------

    handleLabelChange(event) {
        const value = event && event.detail ? event.detail.value : undefined;
        this.newLabel = typeof value === 'string' ? value : '';
    }

    handleAdd() {
        const label = this.readNewTaskLabel();
        if (!label) {
            // Empty / whitespace only labels are ignored: nothing is added and
            // no event is dispatched.
            return;
        }
        this.items = [...this.items, { id: this.generateId(), label, done: false }];
        this.clearNewTaskInput();
        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const element = event.currentTarget || event.target;
        const id = element && element.getAttribute ? element.getAttribute('data-id') : null;
        if (id === null || id === undefined) {
            return;
        }
        // A new array (and new task objects) is assigned so that LWC
        // re-renders the list and the `remaining` counter.
        this.items = this.items.map((task) =>
            String(task.id) === String(id) ? { ...task, done: !task.done } : task
        );
    }
}
