/**
 * GiftImportService
 *
 * Imports one-off website gifts through NPSP's own data import engine
 * (NPSP Data Importer / BDI) instead of inserting Contacts and Opportunities directly.
 *
 * Why we go through the Data Importer
 *  - NPSP's contact matching rules (driven by the org's Data Import Settings,
 *    npsp__Data_Import_Settings__c) are applied, so repeat donors are matched to the
 *    existing Contact instead of creating a duplicate donor.
 *  - NPSP's household / account creation rules are applied for new donors.
 *  - NPSP's donation processing (payment, installment, campaign, rollups) is applied.
 *  - Every gift is staged as an npsp__DataImport__c record. That record stays in the org
 *    and holds the outcome (npsp__Status__c, npsp__FailureInformation__c,
 *    npsp__Contact1Imported__c, npsp__DonationImported__c), which gives us a per-gift
 *    audit trail of exactly what was imported.
 *
 * Design notes
 *  - Bulk safe: one DML statement to stage the rows, one query to read NPSP's results
 *    back. No SOQL and no DML inside loops, so 200 gifts in a single call is fine
 *    (and larger calls are processed in NPSP-sized chunks inside the same transaction).
 *  - Synchronous: everything runs in the caller's transaction - no async / queueable /
 *    batch apex is used, so the caller can rely on the results when importGifts() returns.
 *  - Fault tolerant: a gift that NPSP rejects is reported as a failed ImportResult and
 *    never stops the remaining gifts from being imported.
 */
public class GiftImportService {

    /** A single one-off gift received from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** The outcome of importing a single gift. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /** Value NPSP writes to npsp__Status__c when a row was successfully imported. */
    private static final String STATUS_IMPORTED = 'Imported';

    /** NPSP's own data import batch size - we never hand it more rows than this at once. */
    private static final Integer MAX_RECORDS_PER_API_CALL = 200;

    /** The donation donor is the contact we are matching/creating (Contact1). */
    private static final String DONOR_CONTACT1 = 'Contact1';

    /**
     * Imports the given gifts through NPSP's data import engine.
     *
     * @param gifts gifts received from the website; may be null or empty
     * @return one ImportResult per gift, in the same order as the input list
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(buildStagingRecord(gift));
        }

        // 2. Save the staged records. allOrNone = false, so a row that cannot even be
        //    saved is reported back to the caller instead of rolling back the whole batch.
        List<Database.SaveResult> saveResults = Database.insert(staged, false);

        List<npsp__DataImport__c> processable = new List<npsp__DataImport__c>();
        Map<Integer, String> stagingErrors = new Map<Integer, String>();
        for (Integer i = 0; i < staged.size(); i++) {
            if (saveResults[i].isSuccess()) {
                processable.add(staged[i]);
            } else {
                stagingErrors.put(i, formatSaveErrors(saveResults[i].getErrors()));
            }
        }

        // 3. Run the staged rows through NPSP's import engine, synchronously, in this
        //    transaction. NPSP applies the org's Data Import Settings
        //    (npsp__Data_Import_Settings__c): contact matching on first name / last name /
        //    email, household creation, and donation processing. Because the settings say
        //    never to match existing donations, every gift becomes a new donation.
        Map<Id, String> processingErrors = processWithNpsp(processable);

        // 4. Read back what NPSP wrote onto the Data Import records (single query).
        Map<Id, npsp__DataImport__c> processed = loadProcessedRecords(processable);

        // 5. Build one result per gift, preserving the order of the input list.
        for (Integer i = 0; i < gifts.size(); i++) {
            npsp__DataImport__c stagedRecord = staged[i];
            results.add(buildResult(
                stagedRecord,
                processed.containsKey(stagedRecord.Id) ? processed.get(stagedRecord.Id) : null,
                stagingErrors.get(i),
                processingErrors.get(stagedRecord.Id)
            ));
        }

        return results;
    }

    /**
     * Builds the staged NPSP Data Import record for a gift. Only the fields NPSP needs for
     * contact matching and donation creation are populated; NPSP does the rest.
     */
    private static npsp__DataImport__c buildStagingRecord(WebGift gift) {
        npsp__DataImport__c record = new npsp__DataImport__c();
        if (gift == null) {
            record.npsp__Donation_Donor__c = DONOR_CONTACT1;
            return record;
        }

        record.npsp__Contact1_Firstname__c = trimToNull(gift.firstName);
        record.npsp__Contact1_Lastname__c = trimToNull(gift.lastName);
        record.npsp__Contact1_Personal_Email__c = trimToNull(gift.email);
        record.npsp__Donation_Amount__c = gift.amount;
        record.npsp__Donation_Date__c = gift.giftDate;
        record.npsp__Donation_Donor__c = DONOR_CONTACT1;
        return record;
    }

    /**
     * Hands the staged rows to NPSP's data import API and processes them synchronously.
     *
     * Returns a map of Data Import record Id -> error message for the rows that could not
     * be processed at all. Rows that NPSP simply rejects (the normal case) are not errors
     * here - NPSP records those on the row itself (npsp__Status__c / npsp__FailureInformation__c).
     */
    private static Map<Id, String> processWithNpsp(List<npsp__DataImport__c> records) {
        Map<Id, String> errors = new Map<Id, String>();

        if (records == null || records.isEmpty()) {
            return errors;
        }

        Integer offset = 0;
        while (offset < records.size()) {
            Integer end = Math.min(offset + MAX_RECORDS_PER_API_CALL, records.size());
            List<npsp__DataImport__c> chunk = new List<npsp__DataImport__c>();
            for (Integer i = offset; i < end; i++) {
                chunk.add(records[i]);
            }

            try {
                // NPSP's Apex API for data import. It runs the staged rows through NPSP's
                // import engine (contact matching, household creation, donation
                // processing) using the org's Data Import Settings and writes the outcome
                // back onto each npsp__DataImport__c record. The call is synchronous, so the
                // rows are imported in this transaction. (If your NPSP release exposes a
                // different entry point, e.g. a batch class, only this call needs to change.)
                npsp__DataImportAPI.importRecords(chunk);
            } catch (Exception e) {
                // A failure for one chunk must never abort the other gifts. Any row NPSP
                // did manage to import is picked up from the records themselves below.
                for (npsp__DataImport__c record : chunk) {
                    errors.put(record.Id, 'NPSP data import failed: ' + e.getMessage());
                }
            }

            offset = end;
        }

        return errors;
    }

    /** Loads the results NPSP wrote back onto the staged Data Import records. */
    private static Map<Id, npsp__DataImport__c> loadProcessedRecords(List<npsp__DataImport__c> records) {
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>();

        if (records == null || records.isEmpty()) {
            return processed;
        }

        Set<Id> ids = new Set<Id>();
        for (npsp__DataImport__c record : records) {
            if (record.Id != null) {
                ids.add(record.Id);
            }
        }

        if (ids.isEmpty()) {
            return processed;
        }

        for (npsp__DataImport__c record : [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :ids
        ]) {
            processed.put(record.Id, record);
        }

        return processed;
    }

    /** Builds the result for a single gift from the processed Data Import record. */
    private static ImportResult buildResult(npsp__DataImport__c staged,
                                            npsp__DataImport__c processed,
                                            String stagingError,
                                            String processingError) {
        ImportResult result = new ImportResult();
        result.success = false;

        // The Data Import record itself could not be saved - NPSP never saw this gift.
        if (String.isNotBlank(stagingError)) {
            result.errorMessage = stagingError;
            return result;
        }

        npsp__DataImport__c record = (processed == null) ? staged : processed;
        if (record == null) {
            result.errorMessage = 'The NPSP Data Import record could not be processed.';
            return result;
        }

        String status = record.npsp__Status__c;

        if (status != null && status.equalsIgnoreCase(STATUS_IMPORTED)) {
            // NPSP imported the row: the contact was matched or created and the donation
            // was created.
            result.success = true;
            result.contactId = record.npsp__Contact1Imported__c;
            result.opportunityId = record.npsp__DonationImported__c;
        } else if (String.isNotBlank(record.npsp__FailureInformation__c)) {
            // NPSP rejected the row - surface its own failure information.
            result.errorMessage = record.npsp__FailureInformation__c;
        } else if (String.isNotBlank(processingError)) {
            result.errorMessage = processingError;
        } else if (String.isNotBlank(status)) {
            result.errorMessage = 'NPSP did not import the gift (Data Import status: ' + status + ').';
        } else {
            result.errorMessage = 'NPSP did not import the gift and did not return a failure message.';
        }

        return result;
    }

    /** Formats the errors of a failed DML row into a single message. */
    private static String formatSaveErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'The NPSP Data Import record could not be saved.';
        }

        List<String> messages = new List<String>();
        for (Database.Error err : errors) {
            String fields = (err.getFields() == null || err.getFields().isEmpty())
                ? ''
                : ' [' + String.join(err.getFields(), ', ') + ']';
            messages.add(err.getStatusCode() + ': ' + err.getMessage() + fields);
        }
        return String.join(messages, '; ');
    }

    /** Trims a string and returns null when nothing is left. */
    private static String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return String.isBlank(trimmed) ? null : trimmed;
    }
}
