/**
 * @description Replaces the GAU Allocations of an Opportunity with a percentage based split.
 *
 * The percentages supplied by the caller are the source of truth:
 *  - Every Allocation is written with its npsp__Percent__c value (and the matching
 *    npsp__Amount__c for the current Opportunity Amount).
 *  - npsp__Payment__c is deliberately left empty. NPSP only recalculates the Amount of
 *    percent based (non payment) Allocations when the Amount of the Opportunity changes,
 *    so a $1,000 gift split 60/40 that is later corrected to $2,000 automatically becomes
 *    $1,200 / $800 with no additional code from us.
 *  - The Percentage values must not be edited (and the Amounts must not be hand edited)
 *    afterwards, otherwise NPSP has nothing to recalculate from.
 *
 * All validation happens before any data is changed. If any check fails an
 * AllocationException is thrown; the exception propagates out of the method so the whole
 * transaction (including the delete of the old allocations) is rolled back.
 */
public with sharing class GauAllocationService {

    /** Thrown when the request is invalid or the allocations cannot be saved. */
    public class AllocationException extends Exception {}

    /** Fields that must be writeable in order to save an allocation. */
    private static final Set<String> REQUIRED_ALLOCATION_FIELDS = new Set<String>{
        'npsp__Opportunity__c',
        'npsp__General_Accounting_Unit__c',
        'npsp__Amount__c',
        'npsp__Percent__c'
    };

    /**
     * @description Replaces all existing GAU allocations of the opportunity with one allocation
     *              per entry of percentByGauId.
     * @param opportunityId     The Opportunity the gift belongs to.
     * @param percentByGauId    Map of General Accounting Unit Id to percentage (60 = 60%).
     * @return                  The allocations that were inserted.
     * @throws AllocationException If the input is invalid, a GAU is missing/inactive, or the
     *                             allocations cannot be saved.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // ---------------------------------------------------------------------------------
        // 1. Validate the request. No data is touched until every check below has passed.
        // ---------------------------------------------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required in order to allocate a gift to GAUs.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one General Accounting Unit and percentage are required in order to allocate a gift.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A null General Accounting Unit Id was supplied.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException('No percentage was supplied for General Accounting Unit ' + gauId + '.');
            }
            if (percent <= 0) {
                throw new AllocationException('The percentage for General Accounting Unit ' + gauId + ' must be greater than zero.');
            }
            totalPercent += percent;
        }

        // A total of 100% (or less) is allowed - whatever is left over stays unallocated.
        Decimal roundedTotal = totalPercent.setScale(2, System.Mathmode.HALF_UP);
        if (roundedTotal > 100) {
            throw new AllocationException('The General Accounting Unit percentages add up to ' + roundedTotal + '%, which is more than 100%.');
        }

        // ---------------------------------------------------------------------------------
        // 2. Make sure the running user is allowed to read/write what we need.
        // ---------------------------------------------------------------------------------
        assertAccess();

        // ---------------------------------------------------------------------------------
        // 3. Load and validate the GAUs and the Opportunity.
        // ---------------------------------------------------------------------------------
        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>();
        for (npsp__General_Accounting_Unit__c gau : [
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
        ]) {
            gaus.put(gau.Id, gau);
        }
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit ' + gauId + ' was not found.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit ' + gau.Name + ' is not active and cannot be allocated to.');
            }
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, CampaignId
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found.');
        }
        Opportunity opportunity = opportunities[0];

        // ---------------------------------------------------------------------------------
        // 4. Build the new allocations. The Percentage is stored so that NPSP can keep the
        //    Amounts in sync when the Opportunity Amount is corrected later on.
        // ---------------------------------------------------------------------------------
        Decimal opportunityAmount = opportunity.Amount == null ? 0 : opportunity.Amount;
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Amount__c = roundAmount(opportunityAmount * percent / 100),
                npsp__Percent__c = toStoredPercent(percent)
            );
            // npsp__Payment__c and npsp__Recurring_Donation__c are intentionally left empty:
            // payment linked allocations are not recalculated by NPSP, and this gift is not
            // a recurring donation.
            // The campaign is inherited from the Opportunity so the GAU allocation rolls up
            // to the campaign.
            if (opportunity.CampaignId != null && isFieldCreateable('npsp__Campaign__c')) {
                allocation.npsp__Campaign__c = opportunity.CampaignId;
            }
            allocations.add(allocation);
        }

        // ---------------------------------------------------------------------------------
        // 5. Replace the existing allocations. Delete + insert happen in the same
        //    transaction: if the insert fails the delete is rolled back as well.
        // ---------------------------------------------------------------------------------
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        try {
            if (!existingAllocations.isEmpty()) {
                delete Security.stripInaccessible(AccessType.DELETABLE, existingAllocations);
            }
            List<npsp__Allocation__c> recordsToInsert = Security.stripInaccessible(AccessType.CREATEABLE, allocations);
            insert recordsToInsert;
            // stripInaccessible returns copies, so copy the generated Ids back onto the
            // records we hand back to the caller.
            for (Integer i = 0; i < allocations.size(); i++) {
                allocations[i].Id = recordsToInsert[i].Id;
            }
        } catch (DmlException e) {
            throw new AllocationException(
                'Unable to save the General Accounting Unit allocations for Opportunity ' + opportunityId + ': ' + e.getDmlMessage(0)
            );
        } catch (System.NoAccessException e) {
            throw new AllocationException('Insufficient access to save General Accounting Unit allocations: ' + e.getMessage());
        }

        return allocations;
    }

    // -------------------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------------------

    /** Rounds a currency value to two decimals (half up). */
    private static Decimal roundAmount(Decimal value) {
        return value.setScale(2, System.Mathmode.HALF_UP);
    }

    /**
     * Converts a "human" percentage (60 = 60%) into the value that has to be stored in the
     * npsp__Percent__c field. Percent type fields store the value as a fraction (60% is stored
     * as 0.60), number type fields store the value as supplied (60).
     */
    private static Decimal toStoredPercent(Decimal percent) {
        Schema.DescribeFieldResult fieldDescribe = Schema.SObjectType.npsp__Allocation__c.fields.npsp__Percent__c.getDescribe();
        Integer scale = fieldDescribe.getScale();
        if (fieldDescribe.getType() == Schema.DisplayType.PERCENT) {
            if (scale < 2) {
                scale = 2;
            }
            return (percent / 100).setScale(scale, System.Mathmode.HALF_UP);
        }
        return percent.setScale(scale, System.Mathmode.HALF_UP);
    }

    /** Verifies object and field level access for the records this service reads and writes. */
    private static void assertAccess() {
        if (!Schema.sObjectType.Opportunity.isAccessible()) {
            throw new AllocationException('You do not have access to read Opportunities.');
        }
        if (!Schema.sObjectType.npsp__General_Accounting_Unit__c.isAccessible()) {
            throw new AllocationException('You do not have access to read General Accounting Units.');
        }
        if (!Schema.sObjectType.npsp__Allocation__c.isCreateable()) {
            throw new AllocationException('You do not have access to create General Accounting Unit allocations.');
        }
        if (!Schema.sObjectType.npsp__Allocation__c.isDeletable()) {
            throw new AllocationException('You do not have access to delete General Accounting Unit allocations.');
        }
        Map<String, Schema.SObjectField> allocationFields = Schema.SObjectType.npsp__Allocation__c.fields.getMap();
        for (String fieldName : REQUIRED_ALLOCATION_FIELDS) {
            Schema.SObjectField field = allocationFields.get(fieldName);
            if (field == null || !field.isCreateable()) {
                throw new AllocationException('You do not have access to set the ' + fieldName + ' field on General Accounting Unit allocations.');
            }
        }
    }

    /** Returns true when the running user may create the given field on an allocation. */
    private static Boolean isFieldCreateable(String fieldName) {
        Schema.SObjectField field = Schema.SObjectType.npsp__Allocation__c.fields.getMap().get(fieldName);
        return field != null && field.isCreateable();
    }
}
