/**
 * FamilyService
 *
 * Links children to their parents with NPSP Relationships.
 *
 * How the two records are produced
 * --------------------------------
 * For every child/parent pair this class inserts ONE relationship record:
 * contact = child, related contact = parent, type = 'Parent', status = 'Current'.
 * From the child's point of view the parent therefore shows up as "Parent".
 *
 * The matching record on the parent side is created by NPSP itself.  NPSP
 * Relationships run with the default "List Setting" reciprocal method, so when
 * a relationship of type 'Parent' is saved, NPSP creates the reciprocal
 * relationship and looks the reciprocal type up in the Relationship Lookup
 * setting 'Parent' (Male: Son, Female: Daughter, Neutral: Child).  The parent
 * consequently sees the child as Son / Daughter / Child.
 *
 * Consequence: this class must NOT write the reverse (parent -> child) record
 * itself.  Doing so would leave two relationships in each direction, because
 * NPSP would still create its own reciprocal record.
 *
 * Idempotency
 * -----------
 * Pairs that already have a relationship between the two contacts (in either
 * direction, whatever the type) are skipped, so the import can safely be
 * re-run.  Because the reciprocal record NPSP created also involves the child,
 * a single query over the relationships of the children in the batch is enough
 * to detect every already-linked pair.
 *
 * Bulk safety
 * -----------
 * The complete method costs exactly one SOQL query and one DML statement,
 * no matter how many pairs are passed in.
 */
public with sharing class FamilyService {

    /** Relationship type recorded on the child -> parent relationship. */
    @TestVisible
    private static final String PARENT_RELATIONSHIP_TYPE = 'Parent';

    /** NPSP relationship status picklist value. */
    @TestVisible
    private static final String CURRENT_STATUS = 'Current';

    /** Optional marker written on every relationship created by this service. */
    @TestVisible
    private static final String IMPORT_DESCRIPTION = 'Imported from student system';

    /**
     * Records, for every child/parent pair, that the parent is the child's Parent.
     *
     * @param parentIdByChildId child contact Id -> parent contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Nothing to do for null / empty input.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Normalise the input without touching the database: drop nulls and
        // self-links, and collapse duplicate pairs (the map key already
        // guarantees one parent per child).
        Map<Id, Id> pairs = normalise(parentIdByChildId);
        if (pairs.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>(pairs.keySet());

        // ------------------------------------------------------------------
        // 1 SOQL query: every relationship that touches one of the children.
        // Any relationship between a child and its parent has the child on
        // one of the two lookup fields, so this returns both the
        // child -> parent record and the parent -> child record NPSP created
        // as the reciprocal.
        // ------------------------------------------------------------------
        List<npe4__Relationship__c> existingRelationships = [
            SELECT npe4__Contact__c
                 , npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :childIds
               OR npe4__RelatedContact__c IN :childIds
        ];

        Map<Id, Set<Id>> linkedContacts = buildAdjacency(existingRelationships);

        // ------------------------------------------------------------------
        // Build the records for the pairs that are not linked yet.
        // ------------------------------------------------------------------
        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();
        for (Id childId : pairs.keySet()) {
            Id parentId = pairs.get(childId);

            // Already linked in one (or both) directions -> skip, the import
            // may be re-run.
            if (isLinked(linkedContacts, childId, parentId)) {
                continue;
            }

            // Only the child -> parent record is written here; NPSP creates
            // the reciprocal (parent -> child) record with the type from the
            // Relationship Lookup setting for 'Parent'.
            newRelationships.add(
                new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = PARENT_RELATIONSHIP_TYPE,
                    npe4__Status__c = CURRENT_STATUS,
                    npe4__Description__c = IMPORT_DESCRIPTION
                )
            );
        }

        if (newRelationships.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // 1 DML statement.  allOrNone = false so that a single bad row does
        // not roll back the whole import batch; failures are logged for the
        // caller to pick up.
        // ------------------------------------------------------------------
        List<Database.SaveResult> results = Database.insert(newRelationships, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                System.debug(
                    LoggingLevel.ERROR,
                    'FamilyService: could not create the Parent relationship for child '
                    + newRelationships[i].npe4__Contact__c
                    + ' and parent '
                    + newRelationships[i].npe4__RelatedContact__c
                    + ' : '
                    + results[i].getErrors()[0].getMessage()
                );
            }
        }
    }

    /**
     * Removes entries that cannot be processed (null ids, a contact paired
     * with itself) and returns a clean child -> parent map.
     */
    private static Map<Id, Id> normalise(Map<Id, Id> parentIdByChildId) {
        Map<Id, Id> pairs = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }
            if (childId == parentId) {
                // A contact cannot be their own parent.
                continue;
            }
            pairs.put(childId, parentId);
        }
        return pairs;
    }

    /**
     * Turns the relationship rows into a contact -> set of related contacts map,
     * so a link can be detected regardless of the direction it was stored in.
     */
    private static Map<Id, Set<Id>> buildAdjacency(List<npe4__Relationship__c> relationships) {
        Map<Id, Set<Id>> adjacency = new Map<Id, Set<Id>>();
        for (npe4__Relationship__c relationship : relationships) {
            addNeighbour(adjacency, relationship.npe4__Contact__c, relationship.npe4__RelatedContact__c);
            addNeighbour(adjacency, relationship.npe4__RelatedContact__c, relationship.npe4__Contact__c);
        }
        return adjacency;
    }

    private static void addNeighbour(Map<Id, Set<Id>> adjacency, Id contactId, Id neighbourId) {
        if (contactId == null || neighbourId == null) {
            return;
        }
        if (!adjacency.containsKey(contactId)) {
            adjacency.put(contactId, new Set<Id>());
        }
        adjacency.get(contactId).add(neighbourId);
    }

    /** True when a relationship already exists between the two contacts. */
    private static Boolean isLinked(Map<Id, Set<Id>> adjacency, Id childId, Id parentId) {
        return adjacency.containsKey(childId) && adjacency.get(childId).contains(parentId);
    }
}
