/**
 * OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) trigger handler that creates a follow-up
 * Task for major gifts.
 *
 * Registration (NPSP Settings > Trigger Configuration > Trigger Handler record):
 *   Class Name  : OPP_MajorGiftFollowUp_TDTM
 *   Object      : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order  : 5
 *   Is Asynchronous : false
 *
 * Because there is no Apex trigger on Opportunity, this class runs only while NPSP's
 * TDTM dispatcher finds an active Trigger Handler record pointing at it. Deactivating
 * (or deleting) that Trigger Handler record stops this code from running immediately.
 *
 * Business rule:
 *   Create exactly one Task when an Opportunity is inserted as Closed Won with
 *   Amount >= 5000, or when it is updated so that it becomes Closed Won with
 *   Amount >= 5000 and it was not both of those before the update. Editing an
 *   Opportunity that already qualified must not create a second Task.
 *
 * Bulk/limits design:
 *   - 0 SOQL queries: the "before" state is read from the old records TDTM hands us,
 *     indexed in memory by Id.
 *   - 1 DML statement: the Tasks are handed to NPSP's TDTM DmlWrapper, which performs
 *     a single bulk insert of all Tasks after the trigger context completes.
 *   - 200 Opportunities are handled in a single transaction with no governor-limit risk.
 */
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /** Minimum Opportunity Amount that counts as a major gift. */
    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;

    /** Stage that qualifies a gift. */
    private static final String CLOSED_WON = 'Closed Won';

    /** Number of days after CloseDate on which the thank-you call is due. */
    private static final Integer FOLLOW_UP_DAYS = 3;

    /** Subject used for the generated follow-up Task. */
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    /**
     * Entry point called by NPSP's TDTM dispatcher.
     *
     * @param newlist      the records in the current (new) state
     * @param oldlist      the records in the previous state (AfterUpdate only)
     * @param triggerAction the TDTM action being executed
     * @param objResult    describe information for the object being processed
     * @return a DmlWrapper holding the Tasks NPSP should insert
     */
    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist,
                                                      List<SObject> oldlist,
                                                      npsp.TDTM_Runnable.Action triggerAction,
                                                      Schema.DescribeSObjectResult objResult) {

        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        // Index the previous state by Id so we can tell whether an Opportunity only
        // just became a qualifying major gift. Done in memory -> no SOQL query.
        Map<Id, SObject> oldById = new Map<Id, SObject>();
        if (oldlist != null) {
            for (SObject oldRecord : oldlist) {
                if (oldRecord == null) {
                    continue;
                }
                Id recordId = (Id) oldRecord.get('Id');
                if (recordId != null) {
                    oldById.put(recordId, oldRecord);
                }
            }
        }

        for (SObject newRecord : newlist) {
            if (newRecord == null) {
                continue;
            }

            Opportunity opp = (Opportunity) newRecord;

            // Only Closed Won opportunities of 5000 or more qualify.
            if (!isMajorGift(opp)) {
                continue;
            }

            // Skip opportunities that already qualified before this change:
            // a further edit of an existing major gift must not create another Task.
            Opportunity oldOpp = (Opportunity) oldById.get(opp.Id);
            if (oldOpp != null && isMajorGift(oldOpp)) {
                continue;
            }

            dmlWrapper.addTaskToInsert(buildFollowUpTask(opp));
        }

        return dmlWrapper;
    }

    /**
     * True when the Opportunity is Closed Won and its Amount is 5000 or greater.
     */
    private static Boolean isMajorGift(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        if (opp.StageName != CLOSED_WON) {
            return false;
        }
        return opp.Amount != null && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }

    /**
     * Builds the thank-you call Task for a qualifying Opportunity.
     */
    private static Task buildFollowUpTask(Opportunity opp) {
        Date dueDate = null;
        if (opp.CloseDate != null) {
            dueDate = opp.CloseDate.addDays(FOLLOW_UP_DAYS);
        }

        Task followUp = new Task(
            Subject = TASK_SUBJECT,
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId != null ? opp.OwnerId : UserInfo.getUserId(),
            ActivityDate = dueDate
        );

        if (opp.Name != null) {
            followUp.Description = 'Major gift follow-up call for Opportunity ' + opp.Name + '.';
        }

        return followUp;
    }
}
