```apex
/**
 * ContactImportService
 *
 * Bulk-safe import of legacy contacts.
 *
 * TAF (Trigger Actions Framework 0.3.4) is installed as an unlocked package with no
 * namespace, so its public API (TriggerBase / MetadataTriggerHandler) is referenced
 * directly from this class.
 *
 * Behaviour required by the migration:
 *   - All contacts are inserted with a single DML statement (bulk safe, one trigger
 *     execution, one set of limits consumed).
 *   - The after-insert action `TA_Contact_CreateWelcomeTask` must NOT run, because the
 *     migrated contacts are existing customers and must not receive welcome tasks.
 *   - Every other Contact automation must still run (e.g. the before-insert action
 *     `TA_Contact_FormatPhone` still formats the phone numbers).
 *   - The bypass must be removed again as soon as the DML completes, so that any
 *     contact inserted later in the same transaction still gets its welcome task.
 *
 * Note on the bypass API: `TriggerBase.bypass()` works on the *sObject* level and would
 * disable ALL Contact automation (including the phone formatting). To suppress a single
 * registered action we therefore use `MetadataTriggerHandler.bypass(String actionName)`,
 * which is keyed on the name of the Trigger Action (the name of the handler class
 * registered in TriggerAction__mdt, e.g. 'TA_Contact_CreateWelcomeTask').
 */
public with sharing class ContactImportService {
    /** Name of the Trigger Action (handler class) that must be skipped for imports. */
    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the supplied contacts in a single DML statement, suppressing only the
     * "Send welcome pack" after-insert Trigger Action.
     *
     * @param contacts contacts to insert. Null / empty list is a no-op.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Suppress only the welcome-task action; the before-insert phone formatting
        // action (and any other registered action) keeps running.
        MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION);

        try {
            // Single DML statement for the whole batch.
            insert contacts;
        } finally {
            // Always release the bypass, even if the DML fails, so that contacts
            // inserted later in the same transaction get their welcome task as usual.
            MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION);
        }
    }
}
