**File: force-app/main/default/classes/AccountOwnershipService.cls**

```apex
/**
 * Bulk service used by Sales Operations to move books of business between reps.
 *
 * Behaviour contract:
 *  - The given Accounts and every Contact of those Accounts are re-owned to a single new owner.
 *  - ALL Account trigger actions of the Trigger Actions Framework are bypassed while the
 *    ownership change is applied (TriggerBase.bypass('Account')), because the owner-change
 *    actions recalculate territories and are expensive.
 *  - Contact is NOT bypassed: every Contact trigger action runs normally for the Contact update.
 *  - The Account bypass is always removed in a `finally` block, so Account automation behaves
 *    normally again for the remainder of the transaction, whether the reassignment succeeds
 *    or fails.
 *  - DML is all-or-none and exceptions are never caught or re-wrapped: a failure rolls the
 *    transaction back and propagates to the caller unchanged.
 *  - Volume independent: exactly two SOQL queries and at most two DML statements are used,
 *    no matter how many Accounts or Contacts are involved.
 */
public with sharing class AccountOwnershipService {

    /** Maximum number of Accounts a single call may reassign. */
    public static final Integer MAX_ACCOUNTS_PER_CALL = 200;

    /** Apex transaction limit: maximum number of rows that may be updated in one transaction. */
    private static final Integer MAX_DML_ROWS_PER_TRANSACTION = 10000;

    /** sObject whose TAF actions are bypassed for the ownership change. */
    private static final String ACCOUNT_SOBJECT_NAME = 'Account';

    /**
     * Raised for invalid input only. It is never used to mask, wrap or replace a platform
     * exception (DmlException, LimitException, ...) raised by the DML itself.
     */
    public class AccountOwnershipException extends Exception {
        public AccountOwnershipException(String message) {
            super(message);
        }
    }

    private AccountOwnershipService() {
        // Utility class: no instances.
    }

    /**
     * Re-owns the given Accounts and all of their Contacts to newOwnerId.
     *
     * @param accountIds  Ids of the Accounts to reassign (max 200).
     * @param newOwnerId  Id of the new owner (user or queue).
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (newOwnerId == null) {
            throw new AccountOwnershipException('newOwnerId is required to reassign Account ownership.');
        }
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Defensive copy so we never mutate the caller's collection; drop stray nulls.
        Set<Id> targetAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                targetAccountIds.add(accountId);
            }
        }
        if (targetAccountIds.isEmpty()) {
            return;
        }
        if (targetAccountIds.size() > MAX_ACCOUNTS_PER_CALL) {
            throw new AccountOwnershipException(
                'reassign() supports at most ' + MAX_ACCOUNTS_PER_CALL
                + ' Accounts per call; received ' + targetAccountIds.size() + '.'
            );
        }

        // Query 1 of 2: the Accounts that have to change owner.
        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :targetAccountIds
        ];
        assertAllAccountsFound(accounts, targetAccountIds);

        // Query 2 of 2: every Contact of those Accounts.
        List<Contact> contacts = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :targetAccountIds
        ];

        // With only two DML statements allowed we cannot split the load, so fail fast instead of
        // blowing up half way through the transaction.
        if (accounts.size() + contacts.size() > MAX_DML_ROWS_PER_TRANSACTION) {
            throw new AccountOwnershipException(
                'reassign() would update ' + (accounts.size() + contacts.size())
                + ' records, which exceeds the ' + MAX_DML_ROWS_PER_TRANSACTION
                + ' row DML limit of a transaction. Reassign fewer Accounts per call.'
            );
        }

        for (Account account : accounts) {
            account.OwnerId = newOwnerId;
        }
        for (Contact contact : contacts) {
            contact.OwnerId = newOwnerId;
        }

        try {
            // TAF transaction bypass for the whole Account sObject: no Account trigger action
            // (territory recalculation, roll-ups, ...) runs for this ownership change.
            TriggerBase.bypass(ACCOUNT_OBJECT_NAME);

            // DML 1 of 2: Accounts. All-or-none (partial success is not allowed); on failure the
            // platform throws and the whole transaction is rolled back.
            if (!accounts.isEmpty()) {
                Database.update(accounts, true);
            }

            // DML 2 of 2: Contacts. No bypass on Contact, so every Contact trigger action runs
            // normally. All-or-none as well.
            if (!contacts.isEmpty()) {
                Database.update(contacts, true);
            }
        } finally {
            // Account automation must behave normally for the rest of the transaction,
            // whether the reassignment succeeded or failed.
            TriggerBase.clearBypass(ACCOUNT_OBJECT_NAME);
        }
    }

    /**
     * Guarantees that every requested Account exists and is accessible, so a partially
     * inaccessible batch can never be silently skipped.
     */
    private static void assertAllAccountsFound(List<Account> accounts, Set<Id> targetAccountIds) {
        if (accounts.size() == targetAccountIds.size()) {
            return;
        }
        Set<Id> foundIds = new Map<Id, Account>(accounts).keySet();
        for (Id accountId : targetAccountIds) {
            if (!foundIds.contains(accountId)) {
                throw new AccountOwnershipException(
                    'Account ' + accountId + ' was not found or is not accessible to the running user.'
                );
            }
        }
    }
}
