/**
 * DML-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * Following the Trigger Actions Framework (TAF) recommendation for trigger action
 * unit tests, no records are inserted or updated and no SOQL is executed: the
 * triggerNew / triggerOld lists are built in memory and the action's context
 * method is invoked directly. Record Ids come from the framework's test utility
 * (TriggerTestUtility.getFakeId) so that the action's old-record lookup by Id
 * resolves without needing persisted data.
 *
 * Error assertions use the SObject error API (hasErrors() / getErrors()) and
 * compare the message with the action's ERROR_MESSAGE constant.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    private static final String ERROR_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    /**
     * 1. A reduction of more than half (1000 -> 499) must be rejected with exactly
     *    one error carrying the action's ERROR_MESSAGE.
     */
    @IsTest
    static void moreThanHalfReductionIsRejectedWithSingleError() {
        Id recordId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = recordId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = recordId, Amount = 499);

        Test.startTest();
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assert(newOpp.hasErrors(), 'A reduction of more than half must be rejected.');
        System.assertEquals(
            newOpp.getErrors().size(),
            1,
            'Exactly one error was expected on the record.'
        );
        System.assertEquals(
            newOpp.getErrors()[0].getMessage(),
            ERROR_MESSAGE,
            'The error message must match the action ERROR_MESSAGE constant.'
        );
        System.assertEquals(
            oldOpp.getErrors().size(),
            0,
            'The old record must not carry any error.'
        );
    }

    /**
     * 2. A reduction of exactly half (1000 -> 500) is allowed: the rule only rejects
     *    reductions of MORE than half.
     */
    @IsTest
    static void exactlyHalfReductionIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = recordId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = recordId, Amount = 500);

        Test.startTest();
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assert(!newOpp.hasErrors(), 'A reduction of exactly half must be accepted.');
        System.assertEquals(
            newOpp.getErrors().size(),
            0,
            'No error was expected for a reduction of exactly half.'
        );
    }

    /**
     * 3. An increase (1000 -> 2500) is accepted.
     */
    @IsTest
    static void increaseIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = recordId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = recordId, Amount = 2500);

        Test.startTest();
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assert(!newOpp.hasErrors(), 'An increase must be accepted.');
        System.assertEquals(
            newOpp.getErrors().size(),
            0,
            'No error was expected for an increase.'
        );
    }

    /**
     * 4. A record whose previous Amount was null is accepted and must not raise an
     *    exception (the action guards the null previous amount explicitly).
     */
    @IsTest
    static void nullPreviousAmountIsAcceptedWithoutException() {
        Id recordId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = recordId, Amount = null);
        Opportunity newOpp = new Opportunity(Id = recordId, Amount = 10);

        Test.startTest();
        try {
            TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
            action.beforeUpdate(
                new List<Opportunity>{ newOpp },
                new List<Opportunity>{ oldOpp }
            );
        } catch (Exception e) {
            System.assert(false, 'Unexpected exception was raised: ' + e.getMessage());
        }
        Test.stopTest();

        System.assert(!newOpp.hasErrors(), 'A null previous Amount must not be flagged.');
        System.assertEquals(
            newOpp.getErrors().size(),
            0,
            'No error was expected when the previous Amount was null.'
        );
    }

    /**
     * 5. One call with several records where only some break the rule: exactly the
     *    violating records get the error, all others get none.
     */
    @IsTest
    static void onlyViolatingRecordsInBatchReceiveError() {
        Id violatingId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);
        Id exactlyHalfId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);
        Id increasingId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);
        Id nullPreviousId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        List<Opportunity> triggerNew = new List<Opportunity>();
        List<Opportunity> triggerOld = new List<Opportunity>();

        // Violating record: reduced by more than half.
        triggerOld.add(new Opportunity(Id = violatingId, Amount = 1000));
        triggerNew.add(new Opportunity(Id = violatingId, Amount = 100));

        // Allowed record: reduced by exactly half.
        triggerOld.add(new Opportunity(Id = exactlyHalfId, Amount = 1000));
        triggerNew.add(new Opportunity(Id = exactlyHalfId, Amount = 500));

        // Allowed record: increased.
        triggerOld.add(new Opportunity(Id = increasingId, Amount = 1000));
        triggerNew.add(new Opportunity(Id = increasingId, Amount = 2000));

        // Allowed record: no previous amount.
        triggerOld.add(new Opportunity(Id = nullPreviousId, Amount = null));
        triggerNew.add(new Opportunity(Id = nullPreviousId, Amount = 25));

        Test.startTest();
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        Opportunity violating = triggerNew[0];
        System.assert(violating.hasErrors(), 'The record reduced by more than half must be rejected.');
        System.assertEquals(
            violating.getErrors().size(),
            1,
            'Exactly one error was expected on the violating record.'
        );
        System.assertEquals(
            violating.getErrors()[0].getMessage(),
            ERROR_MESSAGE,
            'The error message must match the action ERROR_MESSAGE constant.'
        );

        System.assert(!triggerNew[1].hasErrors(), 'The record reduced by exactly half must not be flagged.');
        System.assertEquals(triggerNew[1].getErrors().size(), 0, 'No error expected for the exactly-half record.');

        System.assert(!triggerNew[2].hasErrors(), 'The increased record must not be flagged.');
        System.assertEquals(triggerNew[2].getErrors().size(), 0, 'No error expected for the increased record.');

        System.assert(!triggerNew[3].hasErrors(), 'The record with a null previous Amount must not be flagged.');
        System.assertEquals(triggerNew[3].getErrors().size(), 0, 'No error expected for the null previous Amount record.');

        // Only one record in the batch carries an error.
        Integer recordsWithErrors = 0;
        for (Opportunity opp : triggerNew) {
            if (opp.hasErrors()) {
                recordsWithErrors++;
            }
        }
        System.assertEquals(recordsWithErrors, 1, 'Exactly one record in the batch should carry an error.');
    }

    /**
     * Boundary extra: a null new Amount is accepted (the action only compares when
     * both the previous and the new amount are present).
     */
    @IsTest
    static void nullNewAmountIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Schema.SObjectType.Opportunity);

        Opportunity oldOpp = new Opportunity(Id = recordId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = recordId, Amount = null);

        Test.startTest();
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assert(!newOpp.hasErrors(), 'A null new Amount must be accepted.');
        System.assertEquals(newOpp.getErrors().size(), 0, 'No error was expected for a null new Amount.');
    }
