/**
 * Concrete TriggerRecord implementation for the Account object.
 *
 * TAF's entry criteria feature evaluates the Entry_Criteria__c formula of a
 * Trigger_Action__mdt record against a TriggerRecord instance. The names used in
 * the formula are resolved against the properties exposed by the concrete
 * TriggerRecord class, so the fields that take part in the criteria have to be
 * declared here.
 *
 * The framework creates one instance per record of the trigger batch and
 * populates newSobject / oldSobject, therefore this class performs no querying
 * and no per-record work: it remains bulk safe.
 */
public class AccountTriggerRecord extends TriggerRecord {
    private String newRatingValue;
    private String oldRatingValue;

    /**
     * The value of Account.Rating after the update.
     * Falls back to the new record when the value was not pushed in directly.
     */
    public String newRating {
        get {
            if (newRatingValue != null) {
                return newRatingValue;
            }
            return newSobject == null ? null : (String) newSobject.get('Rating');
        }
        set {
            newRatingValue = value;
        }
    }

    /**
     * The value of Account.Rating before the update.
     * Null (blank) when the account had no rating before the update, and also
     * null in the insert context where there is no old record.
     */
    public String oldRating {
        get {
            if (oldRatingValue != null) {
                return oldRatingValue;
            }
            return oldSobject == null ? null : (String) oldSobject.get('Rating');
        }
        set {
            oldRatingValue = value;
        }
    }
}
