/**
 * Trigger Action: normalizes Lead contact information on insert.
 *
 * Registered via Trigger_Action__mdt (DeveloperName: TA_Lead_NormalizeContactInfo)
 * against the sObject_Trigger_Setting__mdt record for Lead, Before Insert context.
 *
 * - Email   : trimmed of leading/trailing whitespace and lower-cased (null stays null)
 * - Company : trimmed of leading/trailing whitespace
 * - LeadSource: set to 'Web' when blank, otherwise left untouched
 *
 * Runs entirely in the before insert context on the in-memory records:
 * no DML, no SOQL, bulk safe (works for a single insert or 200+ records).
 */
public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * Entry point invoked by the Trigger Actions Framework (MetadataTriggerHandler)
     * for the before insert context.
     *
     * @param triggerNew the list of new Lead records (not yet saved)
     */
    public void beforeInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        for (SObject record : triggerNew) {
            Lead lead = (Lead) record;

            // Email: trim whitespace and lower-case; a null email remains null.
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim leading/trailing whitespace only.
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to 'Web' when blank, keep any existing value.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }
}
