/**
 * @description
 * Creates an audit Task on an Opportunity whenever its Amount is changed (after update only).
 *
 * Registered on the Opportunity sObject_Trigger_Setting__mdt record with Order__c 10, so it runs
 * BEFORE TA_Opportunity_RoundAmount (Order__c 20). The rounding action updates the same
 * Opportunities again inside the same transaction, which re-enters this action with a second
 * "old vs new" Amount pair (e.g. 100.50 -> 101). To guarantee at most ONE 'Amount changed' Task
 * per Opportunity per transaction (the rounding is a consequence of the user's change, not a
 * separate one) this action de-duplicates on two levels:
 *
 *   1. auditedOpportunityIds - a static Set of Opportunity Ids already audited during the
 *      current transaction. Apex statics live for the lifetime of the transaction, so a
 *      re-entrant execution of this action simply skips the record.
 *   2. TriggerBase.idToNumberOfTimesSeenAfterUpdate - the framework's own bookkeeping of how
 *      many times a record has already been seen in an after update context. Records already
 *      seen in a previous after update context of this transaction are skipped as well.
 *
 * All Tasks for the batch are written with a single bulk insert (one DML statement per trigger
 * execution), so a 200 record update costs 1 insert and stays well inside the DML limits.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    private static final String TASK_SUBJECT = 'Amount changed';
    private static final String TASK_STATUS = 'Completed';

    /**
     * @description Opportunity Ids already audited in the current transaction.
     *              Static state is reset between transactions, never within one.
     */
    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        List<Task> tasks = new List<Task>();
        Set<Id> loggedIds = new Set<Id>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            if (newOpp == null || newOpp.Id == null) {
                continue;
            }

            Opportunity oldOpp = (triggerOld != null && i < triggerOld.size()) ? triggerOld[i] : null;
            if (oldOpp == null) {
                continue;
            }

            // Only a real Amount change is audited (null -> value and value -> null count too).
            if (!hasAmountChanged(oldOpp.Amount, newOpp.Amount)) {
                continue;
            }

            // One audit Task per Opportunity per transaction.
            if (loggedIds.contains(newOpp.Id) || auditedOpportunityIds.contains(newOpp.Id)) {
                continue;
            }
            if (alreadySeenAfterUpdate(newOpp.Id)) {
                continue;
            }

            loggedIds.add(newOpp.Id);
            tasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = newOpp.Id,
                    Status = TASK_STATUS,
                    Description =
                        'Amount changed from ' + describeAmount(oldOpp.Amount) + ' to ' + describeAmount(newOpp.Amount)
                )
            );
        }

        if (!tasks.isEmpty()) {
            // Mark the records as audited before the DML so a re-entrant execution of this
            // action (the rounding action updating the same records) cannot add a second Task.
            auditedOpportunityIds.addAll(loggedIds);
            insert tasks; // single bulk insert for the whole batch
        }
    }

    /**
     * @description Compares the old and new Amount values by numeric value (scale insensitive).
     */
    private static Boolean hasAmountChanged(Decimal oldAmount, Decimal newAmount) {
        if (oldAmount == null && newAmount == null) {
            return false;
        }
        if (oldAmount == null || newAmount == null) {
            return true;
        }
        return oldAmount.compareTo(newAmount) != 0;
    }

    /**
     * @description True when the framework already processed this record in an after update
     *              context of the current transaction (i.e. this is a re-entrant execution).
     */
    private static Boolean alreadySeenAfterUpdate(Id recordId) {
        Map<Id, Integer> timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate;
        if (timesSeen == null || !timesSeen.containsKey(recordId)) {
            return false;
        }
        Integer count = timesSeen.get(recordId);
        return count != null && count > 1;
    }

    private static String describeAmount(Decimal amount) {
        return (amount == null) ? '(blank)' : String.valueOf(amount);
    }
}
